const ACC_NAMES={"aleabitoreddit": "Serenity", "SemiAnalysis_": "SemiAnalysis", "Omercheema": "Omer Cheema", "OrnnExchange": "Ornn", "HedgeyeTech": "Felix Wang, CFA", "RYANHINGSHING": "Ryan Leung 梁浩盛, CFA", "FredaDuan": "Freda Duan", "TMTLongShort": "Just Another Pod Guy"};
const DIGEST_BY_RANGE={"1": {"intro": "今日材料仅涉及两条社交媒体信息，一条为政治人物对科技公司人事的评论，一条为个股盘中异动，均缺乏可核实的公司公告支撑。", "paragraphs": [{"text": "材料一为唐纳德·特朗普总统就英伟达CEO人事发表的评论，称黄仁勋已辞职，并称只有苹果的蒂姆·库克能接替其位置，措辞为“一位传奇取代另一位传奇”。该表述来自政治人物而非公司公告，材料未提供辞职时间、生效安排或公司回应等细节。", "refs": ["2120901970227818767"]}, {"text": "材料二显示，$ANT在一片上涨中为唯一一只下跌的股票。材料仅给出相对表现描述，未提供跌幅、成交量或具体涨跌数字，也未说明下跌原因，因此无法据此判断其基本面含义。", "refs": ["2124897338489745507"]}, {"text": "综合看，两条材料分别属于人事传闻与个股异动，均缺少一手披露与量化细节。对买方研究而言，前者需以公司正式公告核实，后者需补充价格与成交数据后再评估，当前信息不足以形成判断。", "refs": ["2120901970227818767", "2124897338489745507"]}], "date": "今天", "note": "短评由编辑基于当日抓取内容撰写，每段后标注来源；文中数字均由脚本回查原文核对。本看板仅做信息整理，不构成投资建议。"}, "3": {"intro": "高通车用半导体收入快速逼近传统龙头，SemiAnalysis 给出 2027 年超越英飞凌的路径推演。", "paragraphs": [{"text": "SemiAnalysis 指出，高通车用业务在九月季度收入首次接近 20 亿美元（年化约 80 亿美元），逼近英飞凌的 24.5 亿美元和 NXP 的 20.7 亿美元，并已超越 TI、意法半导体、瑞萨、ADI 和安森美等传统车用半导体公司。", "refs": ["2124337151659651116"]}, {"text": "该机构回溯称，2016 年 10 月高通试图以 470 亿美元收购 NXP 时，NXP 车用业务规模是高通的 8.6 倍；上个季度该比值已降至 1.04 倍。即便没有这桩收购，高通也先后超过了 ADI（2024 年二季度）、安森美（2025 年一季度）、瑞萨（2025 年四季度）、意法半导体（2026 年一季度），以及德州仪器（2026 年三季度，按其估算）。", "refs": ["2124337154021101665"]}, {"text": "增长驱动上，SemiAnalysis 称自 2023 年以来全球轻型车产量基本持平，但高通单车车用收入从 2022 到 2026 年预计增长 3.7 倍（约从 21 美元升到 76 美元），其车用半导体增长与整车销量脱钩，主要由单车价值量提升驱动。", "refs": ["2124337156546080779"]}, {"text": "该机构还列举了高通车用目标的超额完成情况：2024 财年指引 15 亿美元、实际 29 亿；2026 财年指引 35 亿、实际 60 亿；并以 80 亿美元的年化收入收官，比原定 2031 财年目标提前了五年。高通目标 2029 财年车用半导体收入达 100 亿美元。", "refs": ["2124337159041695804"]}, {"text": "关于 2027 年能否超过英飞凌，SemiAnalysis 称取决于季度数据和汇率：英飞凌指引 2027 财年车用业务中双位数增长，按 1.15 欧元/美元约 103 亿美元，两家公司对 12 月季度的指引都是持平。若明年保持 12% 的季度环比增长，高通将在 2027 年一季度超过 NXP，三季度在季度收入上超过英飞凌（28.0 亿 vs 26.8 亿美元），并在 2027 日历年胜出（107 亿 vs 105 亿美元）；若要在 2027 财年就胜出，12 月之后需要 17.5% 的季度增速。", "refs": ["2124337165437960410"]}], "date": "最近 3 天", "note": "短评由编辑基于当日抓取内容撰写，每段后标注来源；文中数字均由脚本回查原文核对。本看板仅做信息整理，不构成投资建议。"}, "7": {"intro": "过去一周，AI交易经历剧烈波动，英伟达因SEC调查传闻和CEO辞职消息承压，同时高通车用半导体崛起与中国云厂商资本开支见顶信号值得关注。", "paragraphs": [{"text": "英伟达股价下跌超过12%，起因是一份新报告称SEC正在调查其潜在会计问题。有推文指出，这家市值5万亿美元以上的公司几周内暴跌46%以上，连带损伤已冲击主要指数和退休投资组合。同时，黄仁勋辞职的消息进一步加剧不确定性，有行业高管透露若黄仁勋不尽快回归，英伟达可能面临员工离职潮，其最大护城河正是黄仁勋做出高风险架构决策的能力。", "refs": ["2123878986686333308", "2123130933318717529", "2123571428712931811"]}, {"text": "高通车用半导体业务增长迅猛。九月季度车用收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元。自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元），增长与整车销量脱钩。其设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元。", "refs": ["2124337151659651116", "2124337156546080779", "2124337161105195142"]}, {"text": "中国云厂商对AI资本开支周期的口风明确。腾讯总裁刘炽平给出AI资本开支应在2027年后放缓的理由：前置投资建成后可持续产出token、到2028年同样设备成本应低得多、效率快速提升使同样基础设施输出指数级更多算力。有分析认为这实际上意味着AI资本开支将在2026-27年见顶，此后资本开支强度明显回落。", "refs": ["2123088477868736729"]}, {"text": "市场对AI相关资产的分歧加剧。有推文统计，卖方对Anthropic（$ANT）只有买入评级，但近期投资者交流中58%的人看空或中性，42%看多。另有观点指出，代币消耗、模型收入和半导体需求是三件截然不同的事情，市场往往将它们视为同一笔交易；在固定水平智能成本每季度下降47%的情况下，其他条件不变时，对这种智能的消耗需要每季度增长约90%才能仅保持相关收入持平。", "refs": ["2123625335547998476", "2124325047120900224"]}], "date": "最近 7 天", "note": "短评由编辑基于当日抓取内容撰写，每段后标注来源；文中数字均由脚本回查原文核对。本看板仅做信息整理，不构成投资建议。"}, "30": {"intro": "本期短评聚焦AI算力链的折旧争议、需求信号与竞争格局变化，并梳理车用半导体与数据中心供给侧的边际信息。", "paragraphs": [{"text": "英伟达股价单日下跌超过12%，起因是一份新报告称SEC正在调查其潜在会计问题；推文提及公司市值曾超5万亿美元、几周内跌幅超46%，并称连带损伤已冲击主要指数和退休投资组合。同日另一推文称AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。上述信息指向事件冲击与跨市场风险传导，但材料未提供调查细节或公司回应。", "refs": ["2123878986686333308", "2123607705969401895"]}, {"text": "围绕GPU抵押价值，Ornn Exchange指出较老的H100与较新的B200、B300、GB300二手市场价格正在跑赢账面价值，认为五年折旧假设对残值偏悲观，转售价值持平甚至上升使GPU成为更强抵押品。该机构同时推出从A100到GB300的折旧曲线，基于真实交易数据建模硬件价值。这是对折旧假设的方法论讨论，尚不构成对会计处理的定论。", "refs": ["2123451571451167047", "2120258550488338902"]}, {"text": "需求侧信号存在分歧。看多方引用CRWV财报称到2027年全年量化需求是算力可用性的10倍；谨慎方则援引Phison CEO称中国近期企业级SSD需求放缓源于自2026年11月以来的GPU短缺，部分公司因缺GPU在现货市场出售服务器组件回收现金。Ornn周报亦称GPU租赁费率未显示AI需求放缓，较旧芯片价格稳定甚至上涨，仅较新的B300走软。", "refs": ["2124318494879780986", "2123647139385684060", "2123658899509375175", "2122013045396259150"]}, {"text": "车用半导体格局出现边际变化。SemiAnalysis称高通九月季度车用收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元；其单车车用收入预计从2022到2026年增长3.7倍（约21美元升至76美元），设计中标管线从2018年初的30亿美元增至2026年6月的650亿美元。该机构判断若明年保持12%的季度环比增长，高通将在2027年三季度季度收入上超过英飞凌（28.0亿 vs 26.8亿美元）。", "refs": ["2124337151659651116", "2124337156546080779", "2124337161105195142", "2124337165437960410"]}, {"text": "数据中心供给端出现政策与物理约束。SemiAnalysis称得克萨斯州环境许可自9月21日起被冻结，当选州长伊诺霍萨主张暂停发放许可直至立法机构通过新规则，例会期为1月12日至5月31日；佐治亚州和俄亥俄州也选出了主张暂停新建数据中心的州长。该机构基于投票前数字判断2027年基本锁定、2028年是争夺焦点，仅得州就贡献2028年美国GW的近30%。", "refs": ["2123602891713708464", "2123602893789962391", "2123602894586818740", "2123602895513755882"]}], "date": "最近 30 天", "note": "短评由编辑基于当日抓取内容撰写，每段后标注来源；文中数字均由脚本回查原文核对。本看板仅做信息整理，不构成投资建议。"}, "all": {"intro": "本期晨报聚焦英伟达管理层变动与AI算力产业链的多重信号，涵盖市场情绪、供应链瓶颈及高通车用半导体的结构性变化。", "paragraphs": [{"text": "英伟达股价下跌超过12%，起因是一份新报告称SEC正在调查其潜在会计问题。有推文提及，一家市值5万亿美元以上的公司几周内暴跌46%以上，连带损伤已冲击主要指数和退休投资组合。同期，AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。", "refs": ["2123878986686333308", "2123607705969401895"]}, {"text": "英伟达CEO黄仁勋已辞职。有行业高管向推文作者表示，若黄仁勋不尽快回归，英伟达可能面临员工离职潮，部分高管和工程师在多年股权上涨后已可退休；同时，市场对英伟达未来增长信心丧失，且公司因黄仁勋离开遭遇信用评级下调。推文作者认为，英伟达最大的护城河是黄仁勋做出高风险架构决策并加速资本、供应商和行业围绕其愿景团结起来。", "refs": ["2120901970227818767", "2123130933318717529", "2123571428712931811"]}, {"text": "全球电子协会就印刷电路板（PCB）供应链日益加剧的短缺发布行业警报，汽车、工业、医疗、国防和电信行业公司报告交货时间延长且难以确保供应。该协会表示，在2028年中期之前不太可能有实质性缓解，并敦促买家提前规划。关键材料短缺包括CCL和玻璃纤维布，正在挤压消费电子产品供应。", "refs": ["2123851594811011470"]}, {"text": "SemiAnalysis认为高通将在2027年成为最大的车用半导体公司。九月季度，高通车用业务收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元。高通已超越TI、意法半导体、瑞萨、ADI和安森美等传统车用半导体公司。自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元）。", "refs": ["2124337151659651116", "2124337154021101665", "2124337156546080779"]}, {"text": "FredaDuan引用Epoch AI估计，自2023年以来实现固定水平AI能力的成本每季度下降约47%；大约每3.5个月就可以用大约一半的参数提供可比性能。在固定水平智能成本每季度下降47%的情况下，其他条件不变时，对这种智能的消耗需要每季度增长约90%才能仅保持相关收入持平。OpenRouter在10月处理的代币量几乎是1月的25倍，而同期有效代币价格下降了57-70%。", "refs": ["2124325047120900224"]}], "date": "全部", "note": "短评由编辑基于当日抓取内容撰写，每段后标注来源；文中数字均由脚本回查原文核对。本看板仅做信息整理，不构成投资建议。"}};
const SUMMARIES={"宏观|7": {"intro": "全球电子协会就PCB供应链短缺发布行业警报，AI吸收稀缺产能正波及汽车、医疗、国防等非AI行业，而美国多州选举结果给数据中心建设带来新的政策不确定性。", "paragraphs": [{"text": "全球电子协会就印刷电路板（PCB）供应链日益加剧的短缺发布行业警报，汽车、工业、医疗、国防和电信行业公司报告交货时间延长且难以确保供应，生产面临风险。该协会表示2028年中期之前不太可能有实质缓解，并敦促买家提前规划。关键材料短缺包括CCL和玻璃纤维布，正挤压消费电子产品供应。@aleabitoreddit 认为这已成为全行业范围的分配问题。", "refs": ["2123851594811011470", "2123859267560304947"]}, {"text": "AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。@HedgeyeTech 指出，随着2027年科技行业前景日益不确定，“便宜”的估值可能因盈利预期被下调而变得更便宜。@aleabitoreddit 则观察到，从$HOOD到$NBIS等成长型股票均大幅下跌，而消费必需品领域估值达到自1999年以来未见的高度。", "refs": ["2123607705969401895", "2123732732505444862", "2123805601411277149"]}, {"text": "美国数据中心建设面临政策变数。@SemiAnalysis_ 指出，得克萨斯州选出了以暂停令为竞选纲领的候选人吉娜·伊诺霍萨，佐治亚州和俄亥俄州也选出了主张暂停新建数据中心建设的州长。得州环境许可自9月21日起被冻结，若审批在整个会期搁置，冻结将持续约八个月。2027年基本锁定，约四分之三待建GW已处于建设中；2028年是争夺焦点，仅得州就贡献2028年美国GW的近30%。", "refs": ["2123602891713708464", "2123602893789962391", "2123602894586818740", "2123602895513755882", "2123602896377753784"]}], "count": 18, "range": "最近 7 天"}, "宏观|30": {"intro": "AI算力扩张的瓶颈正从芯片蔓延至PCB等基础材料，并开始挤压非AI行业；同时，美国数据中心政策不确定性上升，科技股承压。", "paragraphs": [{"text": "全球电子协会就印刷电路板（PCB）供应链日益加剧的短缺发布行业警报，汽车、工业、医疗、国防和电信行业公司报告交货时间延长且难以确保供应。该协会表示，在2028年中期之前不太可能有实质性的缓解。关键材料短缺包括CCL和玻璃纤维布，正在挤压消费电子产品供应。@aleabitoreddit 认为这已成为全行业范围的分配问题。", "refs": ["2123851594811011470"]}, {"text": "美国数据中心政策风险上升。SemiAnalysis 指出，得克萨斯州选出了以暂停令为竞选纲领的候选人吉娜·伊诺霍萨，佐治亚州和俄亥俄州也选出了主张暂停新建数据中心建设的州长。得克萨斯州环境许可自9月21日起被冻结，若审批在整个会期持续搁置，冻结将持续约八个月。2028年是争夺焦点，仅得克萨斯州就贡献了2028年美国GW的近30%。", "refs": ["2123602891713708464", "2123602893789962391", "2123602894586818740", "2123602895513755882", "2123602896377753784"]}, {"text": "科技板块承压。HedgeyeTech 称，随着2027年科技行业前景日益不确定，“便宜”的估值可能因盈利预期被下调而变得更便宜。AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。@aleabitoreddit 观察到，所有成长型股票即便不属于AI领域，从$HOOD到$NBIS，都像是跌下了悬崖。", "refs": ["2123732732505444862", "2123607705969401895", "2123805601411277149"]}], "count": 44, "range": "最近 30 天"}, "宏观|all": {"intro": "AI算力扩张的瓶颈正从芯片蔓延至PCB等基础材料，并开始挤压非AI行业；同时，美国数据中心政策不确定性上升，科技股承压。", "paragraphs": [{"text": "全球电子协会就印刷电路板（PCB）供应链日益加剧的短缺发布行业警报，汽车、工业、医疗、国防和电信行业公司报告交货时间延长且难以确保供应，生产面临风险。该协会表示2028年中期之前不太可能有实质性缓解，并敦促买家提前规划。关键材料短缺包括CCL和玻璃纤维布，正在挤压消费电子产品供应。@aleabitoreddit 认为这已成为全行业范围的分配问题。", "refs": ["2123851594811011470"]}, {"text": "政策层面，@SemiAnalysis_ 指出得克萨斯州选出了以暂停令为竞选纲领的候选人吉娜·伊诺霍萨，佐治亚州和俄亥俄州也选出了主张暂停新建数据中心建设的州长。得州环境许可自9月21日起被冻结，若审批在整个会期搁置，冻结将持续约八个月。2027年基本锁定，2028年是争夺焦点，仅得州就贡献2028年美国GW的近30%。", "refs": ["2123602891713708464", "2123602893789962391", "2123602894586818740", "2123602895513755882", "2123602896377753784"]}, {"text": "市场方面，@HedgeyeTech 称AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。@aleabitoreddit 观察到所有成长型股票即便不属于AI领域，从$HOOD到$NBIS都像是跌下了悬崖，而消费必需品领域估值达到自1999年以来未见的高度。@HedgeyeTech 还提到随着2027年科技行业前景日益不确定，“便宜”的估值可能因盈利预期被下调而变得更便宜。", "refs": ["2123607705969401895", "2123805601411277149", "2123732732505444862"]}], "count": 44, "range": "全部"}, "行业|3": {"intro": "高通车用半导体收入快速逼近传统龙头，而AI智能成本通缩对需求增长提出更高门槛。", "paragraphs": [{"text": "SemiAnalysis指出，高通车用业务在九月季度收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元。自2016年10月试图以470亿美元收购NXP时，NXP车用规模是高通的8.6倍，上个季度该比值已降至1.04倍。高通已先后超越ADI、安森美、瑞萨、意法半导体，并估算在2026年三季度超越德州仪器。", "refs": ["2124337151659651116", "2124337154021101665"]}, {"text": "增长与整车销量脱钩：自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元）。设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，是Mobileye 245亿美元管线的2.6倍以上。上季度计算与连接业务同比增长89%，而英飞凌和NXP只增长10%–13%。", "refs": ["2124337156546080779", "2124337161105195142", "2124337163357610272"]}, {"text": "2027年能否超过英飞凌取决于季度数据和汇率。SemiAnalysis测算，若明年保持12%的季度环比增长，高通将在2027年一季度超过NXP，三季度在季度收入上超过英飞凌（28.0亿 vs 26.8亿美元），并在2027日历年胜出（107亿 vs 105亿美元）。FredaDuan则提示，Epoch AI估计自2023年以来实现固定水平AI能力的成本每季度下降约47%，代币消耗、模型收入和半导体需求并非同一笔交易。", "refs": ["2124337165437960410", "2124325047120900224"]}], "count": 8, "range": "最近 3 天"}, "行业|7": {"intro": "过去一周，车用半导体的竞争格局与AI算力链的定价争议成为讨论焦点。", "paragraphs": [{"text": "SemiAnalysis 认为高通将在2027年成为最大车用半导体公司。其车用业务九月季度收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元。2016年10月高通拟以470亿美元收购NXP时，NXP车用规模是高通的8.6倍，上个季度该比值已降至1.04倍。", "refs": ["2124337151659651116", "2124337154021101665"]}, {"text": "增长与整车销量脱钩。SemiAnalysis 称，自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元）。其设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，是Mobileye 245亿美元管线的2.6倍以上。", "refs": ["2124337156546080779", "2124337161105195142"]}, {"text": "对算力链的谨慎观点同样出现。FredaDuan 引述 Epoch AI 估计，自2023年以来实现固定水平AI能力的成本每季度下降约47%；在成本如此下降时，其他条件不变，智能消耗需每季度增长约90%才能保持相关收入持平。HedgeyeTech 则称，AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。", "refs": ["2124325047120900224", "2123607705969401895"]}], "count": 28, "range": "最近 7 天"}, "行业|30": {"intro": "近期半导体行业讨论聚焦于高通在车用半导体领域的快速崛起，以及AI算力供需与成本效率之间的动态平衡。", "paragraphs": [{"text": "SemiAnalysis指出，高通车用半导体收入在九月季度首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元，并已超越TI、意法半导体、瑞萨、ADI和安森美等传统厂商。自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元），增长与整车销量脱钩。", "refs": ["2124337151659651116", "2124337156546080779"]}, {"text": "SemiAnalysis还提到，高通设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，是Mobileye 245亿美元管线的2.6倍以上。上季度计算与连接业务同比增长89%，而英飞凌和NXP只增长10%–13%。若明年保持12%的季度环比增长，高通将在2027年三季度在季度收入上超过英飞凌（28.0亿 vs 26.8亿美元）。", "refs": ["2124337161105195142", "2124337163357610272", "2124337165437960410"]}, {"text": "FredaDuan引用Epoch AI估计，自2023年以来实现固定水平AI能力的成本每季度下降约47%；OpenRouter在10月处理的代币量几乎是1月的25倍，而同期有效代币价格下降了57-70%。她强调代币消耗、模型收入和半导体需求是三件截然不同的事情，市场往往将它们视为同一笔交易。", "refs": ["2124325047120900224"]}], "count": 28, "range": "最近 30 天"}, "行业|all": {"intro": "本期短评聚焦车用半导体竞争格局与AI算力链的供需信号。", "paragraphs": [{"text": "SemiAnalysis 认为高通车用半导体增长与整车销量脱钩：自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元）。九月季度其车用业务收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元。", "refs": ["2124337156546080779", "2124337151659651116"]}, {"text": "SemiAnalysis 指出，高通设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，是Mobileye 245亿美元管线的2.6倍以上。上季度其计算与连接业务同比增长89%，而英飞凌和NXP只增长10%–13%。该机构测算，若明年保持12%的季度环比增长，高通将在2027年三季度在季度收入上超过英飞凌（28.0亿 vs 26.8亿美元）。", "refs": ["2124337161105195142", "2124337163357610272", "2124337165437960410"]}, {"text": "AI算力链出现分歧信号。FredaDuan 引述 Epoch AI 估计，自2023年以来实现固定水平AI能力的成本每季度下降约47%；OpenRouter 10月处理的代币量几乎是1月的25倍，而同期有效代币价格下降了57-70%。aleabitoreddit 则援引全球电子协会的行业警报称，PCB 供应链短缺已波及汽车、工业、医疗、国防和电信行业，该协会表示2028年中期之前不太可能有实质性缓解。", "refs": ["2124325047120900224", "2123851594811011470"]}], "count": 28, "range": "全部"}, "公司|1": {"intro": "两条推文分别涉及英伟达CEO继任话题与个股异动，信息有限，仅作事实梳理。", "paragraphs": [{"text": "一条推文转述唐纳德·特朗普总统的说法：英伟达CEO黄仁勋已辞职，并称其“做得非常出色”；特朗普认为能接替其位置的只有苹果的蒂姆·库克，称“一位传奇取代另一位传奇”。该表述为转述他人观点，辞职与继任均未见其他材料佐证。", "refs": ["2120901970227818767"]}, {"text": "另一条推文称，$ANT是“在一片上涨中唯一一只下跌的股票”。材料未给出具体涨跌幅、指数或板块范围，仅能确认该账号对$ANT当日相对表现的描述。", "refs": ["2124897338489745507"]}], "count": 2, "range": "今天"}, "公司|3": {"intro": "两条推文分别涉及英伟达人事传闻与个股异动，信息有限，仅作事实梳理。", "paragraphs": [{"text": "一条推文转述唐纳德·特朗普总统的说法：英伟达CEO黄仁勋已辞职，并称其“做得非常出色”；该说法同时提出苹果的蒂姆·库克是唯一能接替其位置的人选，并以“一位传奇取代另一位传奇”作结。上述内容为转述他人观点，材料未提供英伟达方面的确认信息。", "refs": ["2120901970227818767"]}, {"text": "另一条推文提及个股$ANT，称其为“在一片上涨中唯一一只下跌的股票”。材料仅给出这一相对表现描述，未披露具体涨跌幅、时间区间或大盘范围，故不对其成因作任何推断。", "refs": ["2124897338489745507"]}], "count": 2, "range": "最近 3 天"}, "公司|7": {"intro": "过去一周，围绕英伟达、Anthropic及AI资本开支周期的讨论出现明显分歧。", "paragraphs": [{"text": "英伟达股价大幅波动成为焦点。@aleabitoreddit 称，$NVDA 下跌超过12%，起因是一份新报告称SEC正在调查英伟达潜在的会计问题；该推文还提到，一家市值5万亿美元以上的公司几周内暴跌46%以上。@Omercheema 指出，在其跟踪的所有半导体公司里，只有NVDA的交易价格接近52周低点。", "refs": ["2123878986686333308", "2123076524861432038"]}, {"text": "Anthropic IPO引发多空分歧。@HedgeyeTech 称，卖方对$ANT只有买入评级，但其与投资者交流统计显示，58%的人看空或中性，42%看多。@aleabitoreddit 提到$ANT估值达到1.74万亿美元。@OrnnExchange 则追问，Anthropic 8,950亿美元的算力支出如何在其增长轨迹和盈利路径上收回。", "refs": ["2123625335547998476", "2123488317425820130", "2123811370357690494"]}, {"text": "AI资本开支周期出现见顶信号。@FredaDuan 引述腾讯Martin Lau的观点称，AI资本开支应在2027年后放缓，理由包括前置投资、硬件成本下降和效率提升；Martin实际上是在说AI资本开支将在2026-27年见顶。@aleabitoreddit 则提到，$CRWV表示到2027年全年，量化需求是算力可用性的10倍。", "refs": ["2123088477868736729", "2124318494879780986"]}], "count": 25, "range": "最近 7 天"}, "公司|30": {"intro": "英伟达CEO黄仁勋辞职引发市场连锁反应，叠加SEC调查传闻，AI算力板块波动加剧。", "paragraphs": [{"text": "英伟达CEO黄仁勋辞职的消息持续发酵。@aleabitoreddit 援引行业高管称，若黄仁勋不尽快回归，英伟达可能面临员工离职潮，并失去对其未来增长的信心，因为黄仁勋是公司护城河的关键。@HedgeyeTech 则戏称苹果蒂姆·库克是唯一能接替的人选。同时，@aleabitoreddit 提到英伟达因黄仁勋离开遭遇信用评级下调，公司周围充斥极端不确定性。", "refs": ["2123130933318717529", "2120901970227818767", "2123571428712931811"]}, {"text": "市场层面，@aleabitoreddit 称英伟达股价下跌超过12%，起因是SEC调查潜在会计问题的报告，并指出一家市值5万亿美元以上的公司几周内暴跌46%以上。@SemiAnalysis_ 报道英伟达员工大会未接受提问。@Omercheema 观察到，在其跟踪的半导体公司中，只有英伟达交易价格接近52周低点，许多低质量公司仍高出2倍甚至4倍。", "refs": ["2123878986686333308", "2123197114435928513", "2123076524861432038"]}, {"text": "AI算力领域其他动态：Anthropic的S-1文件披露8950亿美元算力承诺，其中约一半需在2030年底前支付（@OrnnExchange）。@FredaDuan 引述腾讯总裁刘炽平（Martin Lau）观点，认为AI资本开支将在2026-27年见顶，2027年后放缓。@aleabitoreddit 提到CoreWeave表示到2027年全年量化需求是算力可用性的10倍，而同一周有人主张算力过剩。", "refs": ["2120663294671221037", "2123088477868736729", "2124318494879780986"]}], "count": 60, "range": "最近 30 天"}, "公司|all": {"intro": "英伟达管理层变动与Anthropic上市预期交织，AI算力链的定价与信心同时承压。", "paragraphs": [{"text": "英伟达成为焦点：@aleabitoreddit称其股价下跌超12%，起因是一份新报告称SEC正在调查潜在的会计问题，并提到这家市值5万亿美元以上的公司几周内暴跌46%以上；@SemiAnalysis_称英伟达召开员工全员大会但未接受提问。@aleabitoreddit另引述行业高管称，若黄仁勋不尽快回归，公司可能面临员工离职潮，并称其离开后公司遭遇信用评级下调。", "refs": ["2123878986686333308", "2123197114435928513", "2123130933318717529", "2123571428712931811"]}, {"text": "Anthropic方面，@OrnnExchange称其S-1文件披露8,950亿美元算力承诺，其中约一半需在2030年底前支付；@aleabitoreddit称其估值达1.74万亿美元。@HedgeyeTech称卖方对$ANT只有买入评级，而其与投资者交流统计显示58%看空或中性、42%看多，并称其调研显示Anthropic增长动能已见顶。", "refs": ["2120663294671221037", "2123488317425820130", "2123625335547998476", "2123035493226975431"]}, {"text": "算力需求侧信号不一：@aleabitoreddit称$CRWV表示到2027年全年量化需求是算力可用性的10倍，同一周却有人主张算力过剩；@OrnnExchange称GPU租赁费率未显示AI需求放缓，较旧芯片稳定甚至上涨，只有较新的B300走软，并称DayOne数据中心相关IPO被搁置。", "refs": ["2124318494879780986", "2122013045396259150", "2123725033272951075"]}], "count": 60, "range": "全部"}, "@FredaDuan|3": {"intro": "智能成本快速通缩之下，代币消耗、模型收入与半导体需求并非同一笔交易。", "paragraphs": [{"text": "Epoch AI估计，自2023年以来，实现固定水平AI能力的成本每季度下降约47%；关于模型能力密度的研究则显示，大约每3.5个月就可以用大约一半的参数提供可比性能。@FredaDuan据此提出，RSI是一个强大的通缩飞轮，智能提升得越快，其生产成本可能下降得越快。", "refs": ["2124325047120900224"]}, {"text": "在固定水平智能成本每季度下降47%的情况下，@FredaDuan测算，其他条件不变时，对这种智能的消耗需每季度增长约90%，才能仅保持相关收入持平。她同时提醒，代币消耗、模型收入和半导体需求是三件截然不同的事情，市场却往往将它们视为同一笔交易。", "refs": ["2124325047120900224"]}, {"text": "需求侧数据同样来自@FredaDuan的引述：OpenRouter在10月处理的代币量几乎是1月的25倍，同期有效代币价格下降57-70%。但她强调，代币的指数级增长不会自动转化为收入的指数级增长，更不用说半导体资本支出的持续增长，三条曲线能否继续一起移动并无保证。", "refs": ["2124325047120900224"]}], "count": 1, "range": "最近 3 天"}, "@FredaDuan|7": {"intro": "腾讯对AI资本开支节奏给出明确判断，而智能成本快速下降正在重塑需求与收入的关系。", "paragraphs": [{"text": "腾讯总裁Martin Lau给出AI资本开支应在2027年后放缓的理由：AI基础设施如建工厂，建成后可持续训练新模型、产出token；到2028年同样设备成本应低得多；效率提升使同等设施输出指数级更多算力和token。@FredaDuan据此判断，AI资本开支将在2026-27年见顶，此后强度明显回落，即使需求仍在增长。", "refs": ["2123088477868736729"]}, {"text": "@FredaDuan引用Epoch AI估计，自2023年以来实现固定水平AI能力的成本每季度下降约47%；模型能力密度研究显示约每3.5个月可用约一半参数提供可比性能。这意味着其他条件不变时，对智能的消耗需每季度增长约90%才能保持相关收入持平。OpenRouter在10月处理的代币量几乎是1月的25倍，同期有效代币价格下降57-70%。", "refs": ["2124325047120900224"]}], "count": 2, "range": "最近 7 天"}, "@FredaDuan|30": {"intro": "腾讯AI资本开支节奏与AI智能成本通缩成为近期讨论焦点。", "paragraphs": [{"text": "段永平（@FredaDuan）引述腾讯总裁刘炽平（Martin Lau）观点，认为AI资本开支应在2027年后放缓，理由包括前置投资建成后可长期使用、2028年硬件成本将更低、效率提升使同等基础设施输出指数级更多算力。段永平据此判断，AI资本开支将在2026-27年见顶，此后强度明显回落，即使需求仍在增长。", "refs": ["2123088477868736729"]}, {"text": "段永平引用Epoch AI数据，自2023年以来实现固定水平AI能力的成本每季度下降约47%；模型能力密度研究显示约每3.5个月可用约一半参数提供可比性能。她指出，在成本每季度降47%下，智能消耗需每季度增约90%才能保持收入持平。OpenRouter 10月代币量近1月的25倍，同期有效代币价格降57-70%。", "refs": ["2124325047120900224"]}], "count": 7, "range": "最近 30 天"}, "@FredaDuan|all": {"intro": "AI资本开支周期与智能成本通缩的博弈：来自@FredaDuan推文的观察。", "paragraphs": [{"text": "Martin Lau给出AI资本开支应在2027年后放缓的理由：前置投资建成后可持续训练新模型、产出token；到2028年同样设备成本应低得多；效率提升使同等基础设施输出指数级更多算力和token。@FredaDuan据此认为，Martin实际上是在说AI资本开支将在2026-27年见顶，此后资本开支强度明显回落，即使AI需求仍在增长。", "refs": ["2123088477868736729"]}, {"text": "@FredaDuan指出，智能成本正快速下降：Epoch AI估计自2023年以来实现固定水平AI能力的成本每季度下降约47%；模型能力密度研究显示约每3.5个月可用约一半参数提供可比性能。在固定水平智能成本每季度下降47%下，其他条件不变时，对这种智能的消耗需每季度增长约90%才能仅保持相关收入持平。", "refs": ["2124325047120900224"]}, {"text": "需求增长方面，@FredaDuan引用OpenRouter数据：10月处理代币量几乎是1月的25倍，同期有效代币价格下降57-70%。但她强调，代币指数级增长不会自动转化为收入指数级增长，更不用说半导体资本支出持续增长；过去相互强化的三条曲线不能保证继续一起移动。", "refs": ["2124325047120900224"]}], "count": 7, "range": "全部"}, "@HedgeyeTech|1": {"intro": "两条推文分别涉及英伟达人事传闻与个股异动，信息量有限，仅作事实梳理。", "paragraphs": [{"text": "推文引述唐纳德·特朗普总统的说法称，英伟达CEO黄仁勋已辞职，并称“现在只有一个人能接替他的位置——苹果的蒂姆·库克”，将其描述为“一位传奇取代另一位传奇”。上述内容为转述他人观点，材料未提供英伟达或苹果方面的任何确认。", "refs": ["2120901970227818767"]}, {"text": "另一条推文提到，$ANT在一片上涨中成为唯一一只下跌的股票。材料仅给出这一相对表现描述，未提供价格、涨跌幅或时间区间等具体数据，故不对其成因作任何推断。", "refs": ["2124897338489745507"]}], "count": 2, "range": "今天"}, "@HedgeyeTech|3": {"intro": "两条推文分别涉及英伟达人事传闻与个股异动，信息有限，仅作事实梳理。", "paragraphs": [{"text": "材料中一条推文转述唐纳德·特朗普总统的说法：英伟达CEO黄仁勋已辞职，并称“只有一个人能接替他的位置——苹果的蒂姆·库克”，还以“一位传奇取代另一位传奇”作评价。该表述为转述他人观点，材料未提供其他信源佐证。", "refs": ["2120901970227818767"]}, {"text": "另一条推文提到$ANT，称其为“在一片上涨中唯一一只下跌的股票”。材料仅给出这一相对表现描述，未提供价格、涨跌幅或时间区间等具体数字。", "refs": ["2124897338489745507"]}], "count": 2, "range": "最近 3 天"}, "@HedgeyeTech|7": {"intro": "HedgeyeTech 近期围绕 AI 交易降温、$ANT IPO 预期差与科技股盈利风险给出系列观察。", "paragraphs": [{"text": "HedgeyeTech 指出，卖方对 $ANT 仍只有买入评级，但其与投资者交流统计显示，58% 的人看空或中性，42% 看多。该机构还称，2026 年 6 月做空 Zai（2513.HK），并就 $ANT 与 OpenAI 之间的蒸馏漏洞和全球价格战向客户发出警告；2026 年 7 月调研显示 Anthropic 增长动能已见顶、OpenAI 复苏，并平掉微软空头。", "refs": ["2123625335547998476", "2123035493226975431"]}, {"text": "市场层面，HedgeyeTech 称 AI 交易大幅下挫，韩国、日本和台湾股指隔夜均下跌 5%，并称台湾是最后一个破裂的 AI 泡沫，其在存储板块持有空头仓位。该机构还提到 DayOne（数据中心相关 IPO）被搁置，$ANT 是“在一片上涨中唯一一只下跌的股票”。", "refs": ["2123607705969401895", "2123731560537149580", "2123725033272951075", "2124897338489745507"]}, {"text": "对于科技板块，HedgeyeTech 认为处境艰难，随着 2027 年科技行业前景日益不确定，“便宜”的估值可能因盈利预期被下调而变得更便宜；其表示正在研究一些更具防御性、可能抵御 AI 下行的标的 $QQQ。", "refs": ["2123732732505444862"]}], "count": 8, "range": "最近 7 天"}, "@HedgeyeTech|30": {"intro": "基于@HedgeyeTech近期推文，梳理其对AI交易、IPO市场及个股的多空观察。", "paragraphs": [{"text": "卖方对$ANT IPO仍以买入评级为主，但@HedgeyeTech与投资者交流统计显示，58%看空或中性，仅42%看多。Kalshi上$ANT IPO概率仍为77%。该机构还称，2026年6月做空Zai（2513.HK），并就$ANT与OpenAI之间的蒸馏漏洞和全球价格战向客户发出警告；7月调研认为Anthropic增长动能已见顶、OpenAI复苏，并平掉微软空头。", "refs": ["2123625335547998476", "2118365501202084335", "2123035493226975431"]}, {"text": "AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。@HedgeyeTech称台湾是最后一个破裂的AI泡沫，并在存储板块持有空头仓位；DayOne（数据中心相关IPO）被搁置。该机构还表示，随着2027年科技行业前景日益不确定，“便宜”的估值可能因盈利预期被下调而变得更便宜，同时正在研究更具防御性、可能抵御AI下行的标的$QQQ。", "refs": ["2123607705969401895", "2123731560537149580", "2123725033272951075", "2123732732505444862"]}, {"text": "个股层面，@HedgeyeTech称$AAOI是光学领域的一颗地雷、出现重大失误；其最近两个做多想法在AI/半导体股这轮暴跌中都没能成功。该机构还提到$ANT是“在一片上涨中唯一一只下跌的股票”。此外，其转述唐纳德·特朗普总统的话称，英伟达CEO黄仁勋已辞职，并称只有苹果的蒂姆·库克能接替他的位置。", "refs": ["2118472569346982283", "2118381633170817225", "2124897338489745507", "2120901970227818767"]}], "count": 13, "range": "最近 30 天"}, "@HedgeyeTech|all": {"intro": "基于@HedgeyeTech近期推文，梳理其对AI交易、IPO市场及个股的看法。", "paragraphs": [{"text": "卖方对$ANT IPO仍一致给出买入评级，但@HedgeyeTech统计其近期与投资者交流显示，58%的人看空或中性，仅42%看多。该机构还称，2026年6月做空Zai（2513.HK）并警告$ANT与OpenAI之间的蒸馏漏洞和全球价格战；7月调研认为Anthropic增长动能见顶、OpenAI复苏，并平掉微软空头。", "refs": ["2123625335547998476", "2123035493226975431"]}, {"text": "AI交易大幅下挫，韩国、日本和台湾股指隔夜均下跌5%。@HedgeyeTech称台湾是最后一个破裂的AI泡沫，并在存储板块持有空头仓位；DayOne（数据中心相关IPO）被搁置。该机构还表示，随着2027年科技行业前景日益不确定，“便宜”的估值可能因盈利预期被下调而变得更便宜。", "refs": ["2123607705969401895", "2123731560537149580", "2123725033272951075", "2123732732505444862"]}, {"text": "个股方面，@HedgeyeTech称$AAOI是光学领域的一颗地雷——重大失误；其最近两个做多想法在AI/半导体股这轮暴跌中都没能成功。Kalshi上$ANT IPO的概率仍为77%。该机构还提到$ANT是“在一片上涨中唯一一只下跌的股票”。", "refs": ["2118472569346982283", "2118381633170817225", "2118365501202084335", "2124897338489745507"]}], "count": 13, "range": "全部"}, "@Omercheema|3": {"intro": "材料仅含两条推文，信息有限，以下短评不作展开。", "paragraphs": [{"text": "@Omercheema 在 2026-11-23 的一条推文中仅以“空头论点。”四字点题，未给出具体论据、标的或数字；同日另一条推文写“黄仁勋回来了……”，同样未附数据与展开说明。两条材料均属表态式表述，缺乏可核验的事实与数字支撑。", "refs": ["2118389341705977961", "2124864761875615954"]}], "count": 2, "range": "最近 3 天"}, "@Omercheema|7": {"intro": "@Omercheema 近一周的推文围绕半导体估值分化、复苏路径与竞争机制展开。", "paragraphs": [{"text": "@Omercheema 指出，在其跟踪的所有半导体公司里，只有 NVDA 的交易价格接近 52 周低点，而许多低质量公司仍高出 2 倍甚至 4 倍，并点名 AMS、AEHR、WOLF、SIVE、AAOI 等。他同时发问：这会是 V 型复苏还是 U 型复苏。", "refs": ["2123076524861432038", "2123862479683899849"]}, {"text": "关于竞争与协调，@Omercheema 借 90 年代一位俄罗斯面包官员访问伦敦的故事说明：伦敦没有中央面包管理局，也无主食价格控制，农民、磨坊主、面包师和零售商相互竞争，结果面包充足、多样且相对便宜。他的结论是：资本主义行之有效，健康的竞争行之有效，不健康的竞争壁垒则不然。", "refs": ["2123352600783225261"]}, {"text": "在预期管理上，@Omercheema 表示没人知道未来，重新审视估算没有错，分析师们一直这么做。此外他提到五年内市值达到 1.x 万亿美元是惊人的成就，并称黄仁勋回来了。", "refs": ["2123353742871310697", "2123487859201991037", "2124864761875615954"]}], "count": 9, "range": "最近 7 天"}, "@Omercheema|30": {"intro": "买方研究编辑整理@Omercheema近30天推文，聚焦半导体估值、并购与竞争格局。", "paragraphs": [{"text": "估值分化显著：@Omercheema指出，在其跟踪的所有半导体公司中，只有NVDA交易价格接近52周低点，而AMS、AEHR、WOLF、SIVE、AAOI等低质量公司仍高出2倍甚至4倍。他提出经验法则：查看今年4月1日的半导体股票价格，如果现在低于那个价格，可能值得买入；并称若再有三天像今天这样的行情，就会进入坚实的买入区间。", "refs": ["2123076524861432038", "2118367141262999873", "2118407018126201021"]}, {"text": "并购与竞争：@Omercheema对Marvell收购Lumentum的估值表示担忧，称按当前估值这将是一笔糟糕的交易，若AI采用遇阻，1150亿美元在几年后可能显得昂贵。他预计从下个季度开始，AMD季度营收将超过英特尔，为史上首次。关于英特尔，他称以色列生产问题不是英特尔的错，是运气不好，但基板不够绝对是他们的错，供应链负责人应该被解雇。", "refs": ["2117533295453802977", "2115728144942702788", "2117949868647825649", "2116025072486097307", "2116042705214021763"]}], "count": 22, "range": "最近 30 天"}, "@Omercheema|all": {"intro": "半导体板块分化与估值争议交织，@Omercheema 近期推文聚焦个股相对表现、并购估值与行业竞争格局。", "paragraphs": [{"text": "在 @Omercheema 跟踪的所有半导体公司中，只有 NVDA 的交易价格接近 52 周低点，而许多低质量公司仍高出 2 倍甚至 4 倍，包括 AMS、AEHR、WOLF、SIVE、AAOI 等。他提出经验法则：查看今年 4 月 1 日的半导体股票价格，如果现在低于那个价格，可能值得买入；并称若再有三天像今天这样的行情，就会进入坚实的买入区间。", "refs": ["2123076524861432038", "2118367141262999873", "2118407018126201021"]}, {"text": "关于 Marvell 收购 Lumentum，@Omercheema 最大的担忧是估值：半导体股票正处于回调中，如果 AI 采用遇到障碍，1150 亿美元在几年后可能显得昂贵；他明确表示按当前估值，这笔收购将是一笔糟糕的交易。此外，他预计从下个季度开始，AMD 的季度营收将超过英特尔，为史上首次。", "refs": ["2117533295453802977", "2115728144942702788", "2117949868647825649"]}], "count": 22, "range": "全部"}, "@OrnnExchange|7": {"intro": "Ornn 本周材料聚焦 GPU 残值、算力远期曲线与需求悖论三条线索。", "paragraphs": [{"text": "Ornn 对折旧假设提出质疑：按 @OrnnExchange 的说法，较老的 H100 与较新的 B200、B300、GB300 的二手市场价格正在跑赢账面价值；对放贷方而言，这些 GPU 在继续产生租赁收入的同时，转售价值还能持平甚至上升，使其成为比标准五年折旧假设更强的抵押品。", "refs": ["2123451571451167047"]}, {"text": "在合约定价工具上，Ornn 已推出历史远期曲线，覆盖从 A100 到 GB300 的长期算力合约历史趋势，用户可将任意 GPU 曲线设定到过去某个日期，或固定多个日期在同一张图表上比较。@OrnnExchange 称，石油和天然气等成熟市场长期追踪远期曲线以对标价格并管理期限风险，算力现在也有了这样的历史。", "refs": ["2123076265359851737"]}, {"text": "需求侧，@OrnnExchange 用一张图概括杰文斯悖论：代币越来越便宜，需求爆炸式增长，算力却越来越贵，并直言“算力胜过石油”。另据其引述，Dario Amodei 在 CNBC 上就 Anthropic 8,950 亿美元的算力支出如何在其增长轨迹和盈利路径上收回给出了看法。", "refs": ["2123600228452360484", "2124177379773894895", "2123811370357690494"]}], "count": 5, "range": "最近 7 天"}, "@OrnnExchange|30": {"intro": "Ornn Exchange 近期推文聚焦 GPU 残值、算力定价基准与 Anthropic 的巨额算力承诺，以下基于材料事实梳理。", "paragraphs": [{"text": "Ornn 数据显示，较老的 H100 与较新的 B200、B300、GB300 的二手市场价格正在跑赢账面价值。对放贷方而言，这些 GPU 在继续产生租赁收入的同时，转售价值还能持平甚至上升，使其成为比标准五年折旧假设更强的抵押品。", "refs": ["2123451571451167047"]}, {"text": "Anthropic 的 S-1 文件披露了 8950 亿美元的算力承诺，其中约一半需在 2030 年底前支付。Ornn 提出，Anthropic 需要多少收入才能覆盖这些承诺，并引用 Dario Amodei 在 CNBC 上的看法。", "refs": ["2121276653724664170", "2120663294671221037", "2123811370357690494"]}, {"text": "Ornn 指出，市场仍未就算力的价值达成共识，缺乏共享的定价基准和标准化合同，没有可靠的费率可用于对冲、借贷或交易。Ornn 已推出历史远期曲线，展示从 A100 到 GB300 的长期算力合约的历史趋势。", "refs": ["2124869327794925947", "2123076265359851737"]}], "count": 15, "range": "最近 30 天"}, "@OrnnExchange|all": {"intro": "Ornn 系列推文围绕 GPU 残值、算力定价基准与 Anthropic 的算力承诺展开，核心争议在于折旧假设与抵押品价值。", "paragraphs": [{"text": "Ornn 指出，较老的 H100 与较新的 B200、B300、GB300 的二手市场价格正在跑赢账面价值；对放贷方而言，这些 GPU 在继续产生租赁收入的同时，转售价值还能持平甚至上升，使其成为比标准五年折旧假设更强的抵押品。该账号同时发问：五年折旧安排对 GPU 残值来说是否过于悲观。", "refs": ["2123451571451167047"]}, {"text": "需求侧，Ornn 称 Anthropic 的 S-1 文件披露了 8950 亿美元的算力承诺，其中约一半需在 2030 年底前支付；该账号追问 Anthropic 需要多少收入才能覆盖这些承诺，并提到 Dario Amodei 在 CNBC 上给出了看法。Ornn 另称已推出从 A100 到 GB300 的历史远期曲线，用于对标价格与管理期限风险。", "refs": ["2121276653724664170", "2120663294671221037", "2123811370357690494", "2123076265359851737"]}, {"text": "Ornn 认为市场仍未就算力价值达成共识：缺乏共享的定价基准和标准化合同，没有可靠费率可用于对冲、借贷或交易。该账号称其价格指数追踪的是买家实际支付的价格，而非挂牌价格，并已推出利用真实交易数据建模 A100 到 GB300 硬件价值的折旧曲线。", "refs": ["2124869327794925947", "2120888848007811332", "2120258550488338902"]}], "count": 15, "range": "全部"}, "@RYANHINGSHING|7": {"intro": "基于@RYANHINGSHING 近7天公开可见内容，梳理其对半导体与AI模型公司关联的观察。", "paragraphs": [{"text": "作者称近期一直在研究模型公司，理由是这些公司对半导体影响很大，并提到中国AI模型公司似乎把战略转向Pro。上述判断仅为公开预览所呈现的方向性表述，完整论证未公开。", "refs": ["2123401758194184292"]}, {"text": "就Ant上市，作者提出一种推演：按理说上市会抽走流动性，同时波动率上升会让半导体股大跌，这次是回踩低位；但其后续判断因订阅限制未显示。另就中国市场，作者反问：英伟达在中国卖出大量芯片，凭什么指望AMD不在中国卖芯片。", "refs": ["2123787556626321770", "2124023634436235372"]}], "count": 4, "range": "最近 7 天"}, "@RYANHINGSHING|30": {"intro": "围绕AI算力、芯片出口与模型公司竞争，@RYANHINGSHING 近期推文呈现了多条分析线索。", "paragraphs": [{"text": "作者指出，美国对华鹰派推动全面断供AI芯片算力，但中国至今仍大量走私Nvidia芯片且政府默许，走私量难以打击一半以上。他认为智谱和deepseek的infra能力很强，封锁会加速其使用昇腾训练万亿规模模型，独立AI生态圈将形成。", "refs": ["2121651038625444254", "2112466724901810207"]}, {"text": "作者引用范兄观点称，后训练的开源推理模型小、Token成本小、收集优质data和eval进度慢，因此后训练带来的算力和进度不会很快。他同时认为，能锁定算力和国产技术栈整合的独立模型公司有明显优势，而Minimax基础设施太差。", "refs": ["2118355323547496489", "2122697107912249372", "2122705041383637306"]}, {"text": "作者强调，中国使用海外算力本质是为美国AI与半导体生态支付高额费用，美国云厂商与inference providers靠中国开源模型已累积达10亿美元的推理ARR。他批评对华鹰派主张短视，并认为Nvidia与中国的工程师合作反而巩固CUDA生态主导地位。", "refs": ["2121632138659520706"]}], "count": 32, "range": "最近 30 天"}, "@RYANHINGSHING|all": {"intro": "围绕AI算力、芯片出口与模型公司竞争，@RYANHINGSHING 近期推文呈现了多条分析线索。", "paragraphs": [{"text": "作者指出，美国对华鹰派推动全面断供AI芯片，但中国至今仍大量走私Nvidia芯片，政府默许走私；BIS封堵远程算力主要限制中国AI公司在海外训练前沿模型。作者认为，走私算力很难打击，能打击一半走私量已是超级乐观，智谱和deepseek应能较优先取得算力。", "refs": ["2121651038625444254", "2122698386596098424", "2112466724901810207"]}, {"text": "作者引用范兄观点称，后训练的开源推理模型小、Token成本小、收集优质data和eval进度慢，因此后训练带来的算力和进度不会很快。作者还提到，美国云厂商与inference providers靠中国开源模型已累积可观推理ARR（达10亿美元），而中国lab实际收到的licensing fee非常有限。", "refs": ["2118355323547496489", "2121632138659520706"]}, {"text": "作者认为，能锁定算力和国产技术栈整合的独立模型公司有明显优势，$ANT的竞争压力短期内会减低，值得更高估值。作者还表示，中长期不对智谱和deepseek悲观，对华鹰派行为会加速二者使用昇腾训练万亿规模模型和推理。", "refs": ["2122697107912249372", "2122708740243877928", "2112466724901810207"]}], "count": 32, "range": "全部"}, "@SemiAnalysis_|3": {"intro": "高通车用半导体收入快速逼近传统龙头，但2027年能否登顶仍取决于增速与汇率。", "paragraphs": [{"text": "SemiAnalysis 指出，高通九月季度车用业务收入首次接近 20 亿美元（年化约 80 亿美元），逼近英飞凌的 24.5 亿美元和 NXP 的 20.7 亿美元，并已超越 TI、意法半导体、瑞萨、ADI 和安森美。2016 年 10 月高通拟以 470 亿美元收购 NXP 时，NXP 车用规模是高通的 8.6 倍，上个季度该比值已降至 1.04 倍。", "refs": ["2124337151659651116", "2124337154021101665"]}, {"text": "增长与整车销量脱钩：自 2023 年以来全球轻型车产量基本持平，而高通单车车用收入从 2022 到 2026 年预计增长 3.7 倍（约从 21 美元升到 76 美元）。设计中标管线从 2018 年初的 30 亿美元增长 22 倍，到 2026 年 6 月达 650 亿美元，是 Mobileye 245 亿美元管线的 2.6 倍以上。", "refs": ["2124337156546080779", "2124337161105195142"]}, {"text": "SemiAnalysis 测算，若明年保持 12% 的季度环比增长，高通将在 2027 年一季度超过 NXP，三季度在季度收入上超过英飞凌（28.0 亿 vs 26.8 亿美元），并在 2027 日历年以 107 亿 vs 105 亿美元胜出；若要在 2027 财年就胜出，12 月之后需要 17.5% 的季度增速。上季度其计算与连接业务同比增长 89%，英飞凌和 NXP 只增长 10%–13%。", "refs": ["2124337165437960410", "2124337163357610272"]}], "count": 10, "range": "最近 3 天"}, "@SemiAnalysis_|7": {"intro": "高通车用半导体收入快速逼近传统龙头，2027年能否登顶取决于增速与汇率。", "paragraphs": [{"text": "高通车用业务在九月季度收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元，并已超越TI、意法半导体、瑞萨、ADI和安森美等传统车用半导体公司。自2016年10月高通试图以470亿美元收购NXP时，NXP车用业务规模是高通的8.6倍，上个季度该比值已降至1.04倍。", "refs": ["2124337151659651116", "2124337154021101665"]}, {"text": "自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元），增长与整车销量脱钩。高通设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，是Mobileye 245亿美元管线的2.6倍以上。上季度计算与连接业务同比增长89%，而英飞凌和NXP只增长10%–13%。", "refs": ["2124337156546080779", "2124337161105195142", "2124337163357610272"]}, {"text": "2027年能否超过英飞凌取决于季度数据和汇率。英飞凌指引2027财年车用业务中双位数增长，按1.15欧元/美元约103亿美元，两家公司对12月季度的指引都是持平。若明年保持12%的季度环比增长，高通将在2027年一季度超过NXP，三季度在季度收入上超过英飞凌（28.0亿 vs 26.8亿美元），并在2027日历年胜出（107亿 vs 105亿美元）。若要在2027财年就胜出，12月之后需要17.5%的季度增速。", "refs": ["2124337165437960410"]}], "count": 24, "range": "最近 7 天"}, "@SemiAnalysis_|30": {"intro": "高通车用半导体收入快速逼近传统龙头，但2027年能否登顶仍取决于增速与汇率。", "paragraphs": [{"text": "SemiAnalysis称，高通九月季度车用业务收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元，并已超越TI、意法半导体、瑞萨、ADI和安森美。相较2016年10月拟以470亿美元收购NXP时NXP车用规模为高通的8.6倍，上季度该比值已降至1.04倍。", "refs": ["2124337151659651116", "2124337154021101665"]}, {"text": "增长与整车销量脱钩：自2023年以来全球轻型车产量基本持平，但高通单车车用收入2022至2026年预计增长3.7倍，约从21美元升至76美元。其设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，为Mobileye 245亿美元管线的2.6倍以上。", "refs": ["2124337156546080779", "2124337161105195142"]}, {"text": "SemiAnalysis测算，若明年保持12%的季度环比增长，高通将在2027年一季度超过NXP，三季度在季度收入上超过英飞凌（28.0亿 vs 26.8亿美元），并在2027日历年以107亿 vs 105亿美元胜出；若要在2027财年就胜出，12月之后需17.5%的季度增速。该文亦指出，英飞凌按其CEO预期在2027财年后保持约10%年增长将做到约124亿美元。", "refs": ["2124337165437960410", "2124337159041695804"]}], "count": 24, "range": "最近 30 天"}, "@SemiAnalysis_|all": {"intro": "高通车用半导体收入快速逼近传统龙头，2027年能否登顶成为焦点。", "paragraphs": [{"text": "高通车用业务在九月季度收入首次接近20亿美元（年化约80亿美元），逼近英飞凌的24.5亿美元和NXP的20.7亿美元，并已超越TI、意法半导体、瑞萨、ADI和安森美。相比2016年10月试图收购NXP时NXP车用规模是高通的8.6倍，上季度该比值已降至1.04倍。", "refs": ["2124337151659651116", "2124337154021101665"]}, {"text": "自2023年以来全球轻型车产量基本持平，但高通单车车用收入从2022到2026年预计增长3.7倍（约从21美元升到76美元），增长与整车销量脱钩。设计中标管线从2018年初的30亿美元增长22倍，到2026年6月达650亿美元，是Mobileye 245亿美元管线的2.6倍以上。", "refs": ["2124337156546080779", "2124337161105195142"]}, {"text": "高通绕开电源芯片、微控制器等正面竞争，切入数字座舱、ADAS和连接，上季度该业务同比增长89%，而英飞凌和NXP只增长10%–13%。若明年保持12%的季度环比增长，高通将在2027年三季度季度收入上超过英飞凌（28.0亿 vs 26.8亿美元），并在2027日历年胜出（107亿 vs 105亿美元）。", "refs": ["2124337163357610272", "2124337165437960410"]}], "count": 24, "range": "全部"}, "@TMTLongShort|30": {"intro": "买方人才稀缺性与智力评估的讨论，兼及白领结构变化的社会后果。", "paragraphs": [{"text": "作者指出，pod中“最好的”高级PM每天花一半时间与新潜在候选人交谈，但鉴于真正的人才多么稀有，他们往往要连续几年才能找到一个真正的异常值；平庸PM在pod间跳来跳去，是满足于“足够好”的分析师或副PM，其PnL要么无法扩展，要么crush三年然后爆仓。这解释了Citadel偶尔提供与基线相差悬殊的薪酬方案，以及标准化薪酬商店沦为平庸或需要Izzy拯救。", "refs": ["2117038995536281895"]}, {"text": "作者认为，表面上最负盛名的基金中99%的人，在智力上至少比Shaun或AI实验室的核心研究人员低一个标准差；Shaun的智力水平与买方中位数之间的差距，比买方中位数与他们高中班级里最迟钝的孩子之间的差距还要大。作者称，真正有天赋的人会在礼貌场合淡化能力，而多数金融推特用户把相对大众的智力优势当作全部身份认同。", "refs": ["2116981066380796409"]}, {"text": "作者提出，现代经济一直将中等能动性、高智力的个体引导到制度化的低效工厂中，一旦这种结构崩溃，就会看到俄国和法国大革命或明治维新；失业的聪明人能够操纵不如他们聪明的同谋者，并以芝加哥贫民窟看不到的方式调动资源。作者认为唯一解决方案是说服他们：A. 他们比以前过得更好；B. 他们比世界其他地方的人过得更好。", "refs": ["2115114421823357068"]}], "count": 16, "range": "最近 30 天"}, "@TMTLongShort|all": {"intro": "从买方人才稀缺性到智力评估的误区，@TMTLongShort 的推文呈现了对精英行业生态的批判性观察。", "paragraphs": [{"text": "作者指出，pod 中“最好的”高级 PM 每天花一半时间寻找候选人，但真正的人才极为稀有，往往要连续几年才能找到一个真正的异常值。平庸 PM 在 pod 之间跳来跳去，满足于“足够好”的分析师，其 PnL 要么无法扩展，要么 crush 三年然后爆仓。这解释了 Citadel 偶尔提供与基线相差悬殊的薪酬方案，以及标准化薪酬的商店沦为平庸或需要 Izzy 来拯救。", "refs": ["2117038995536281895"]}, {"text": "作者批评金融推特的匿名用户因被智力中等的人包围而产生虚假优越感，认为在买方或常春藤获得席位就非凡。他称 Shaun 的智力水平与买方中位数之间的差距，比买方中位数与高中班级最迟钝孩子之间的差距还要大，并估计表面上最负盛名的基金中 99% 的人，在智力上至少比 Shaun 或 AI 实验室核心研究人员低一个标准差。", "refs": ["2116981066380796409"]}], "count": 16, "range": "全部"}, "@aleabitoreddit|7": {"intro": "近期AI与半导体板块波动加剧，市场对需求真实性与供应链瓶颈的解读出现显著分歧。", "paragraphs": [{"text": "英伟达因SEC调查会计问题的报告单日下跌超12%，作者称一家市值5万亿美元以上的公司几周内暴跌46%以上，连带损伤冲击主要指数和退休投资组合。同时，作者引述行业高管观点称，若黄仁勋不尽快回归，英伟达可能面临员工离职潮，且公司遭遇信用评级下调，围绕英伟达的极端不确定性上升。", "refs": ["2123878986686333308", "2123130933318717529", "2123571428712931811"]}, {"text": "需求信号相互矛盾：CoreWeave表示到2027年全年量化需求是算力可用性的10倍，但同一周有人主张算力过剩。存储端，Phison CEO将中国近期企业级SSD需求放缓归因于自2026年11月以来的GPU短缺，并称没有GPU额外采购价值不大。作者认为市场错误地将中国eSSD削减解读为需求恶化和NAND供应过剩。", "refs": ["2124318494879780986", "2123647139385684060", "2123658899509375175", "2123633356969775107"]}, {"text": "供应链瓶颈扩散：全球电子协会就PCB供应链日益加剧的短缺发布行业警报，汽车、工业、医疗、国防和电信公司报告交货时间延长且难以确保供应，该协会称2028年中期之前不太可能有实质缓解。作者指出关键材料短缺包括CCL和玻璃纤维布，正挤压消费电子产品供应，并认为抛售开始看起来与基本面需求脱节。", "refs": ["2123851594811011470"]}], "count": 21, "range": "最近 7 天"}, "@aleabitoreddit|30": {"intro": "AI与半导体板块近期波动加剧，市场对需求真实性与供应链瓶颈的解读出现显著分歧。", "paragraphs": [{"text": "英伟达因SEC调查会计问题的报道单日下跌超12%，作者指出其市值曾超5万亿美元、几周内跌幅逾46%，连带损伤已冲击主要指数和退休投资组合。同时，作者援引行业高管称，若黄仁勋不尽快回归，英伟达或面临员工离职潮，并认为其最大护城河正是黄仁勋的高风险架构决策能力。", "refs": ["2123878986686333308", "2123130933318717529", "2123571428712931811"]}, {"text": "需求信号相互矛盾：CRWV称到2027年量化需求是算力可用性的10倍，而市场同期却在主张算力过剩。存储端，Phison CEO将中国eSSD需求放缓归因于2026年11月以来的GPU短缺，并称无GPU时额外采购价值不大。作者认为市场错误地将中国eSSD削减解读为NAND需求恶化。", "refs": ["2124318494879780986", "2123647139385684060", "2123658899509375175", "2123633356969775107"]}, {"text": "供应链瓶颈扩散至非AI行业。全球电子协会就PCB短缺发布行业警报，称汽车、工业、医疗、国防和电信企业交货时间延长，2028年中期前不太可能有实质缓解。作者还以ESMT为例：市值15.8亿美元、净现金7.47亿美元、第三季度自由现金流3.495亿美元，调整后企业价值5.593亿美元，而第三季度净利润3.27亿美元。", "refs": ["2123851594811011470", "2123598186065559858"]}], "count": 21, "range": "最近 30 天"}, "@aleabitoreddit|all": {"intro": "在AI与半导体板块剧烈波动之际，材料呈现了从个股暴跌、供应链瓶颈到管理层风险的多重叙事。", "paragraphs": [{"text": "英伟达因SEC调查会计问题的报告单日下跌超12%，作者指出其市值曾超5万亿美元、几周内跌幅超46%，连带损伤已冲击主要指数和退休投资组合。同时，作者援引行业高管称，若黄仁勋不尽快回归，英伟达可能面临员工离职潮，并认为其最大护城河正是黄仁勋的高风险架构决策能力。", "refs": ["2123878986686333308", "2123130933318717529"]}, {"text": "供应链紧张正从AI外溢。全球电子协会就PCB短缺发布行业警报，称汽车、工业、医疗、国防和电信企业交货时间延长，实质缓解预计要到2028年中期；CCL和玻璃纤维布短缺也在挤压消费电子。作者认为，短缺加剧且范围扩大，可能表明抛售开始与基本面需求脱节。", "refs": ["2123851594811011470"]}, {"text": "存储与算力需求信号矛盾。作者引述Phison CEO称，中国近期企业级SSD需求放缓源于自2026年11月以来的GPU短缺；而CRWV财报显示到2027年全年量化需求是算力可用性的10倍。作者还以ESMT为例：调整后企业价值5.593亿美元，第三季度净利润3.27亿美元，年化市盈率1.2倍。", "refs": ["2123647139385684060", "2124318494879780986", "2123598186065559858"]}], "count": 21, "range": "全部"}};
const DIGEST={"date": "2026-11-18 → 11-22", "title": "今日短评", "intro": "本期共 8 个账号、53 条推文；短评只覆盖 11-18 至 11-22 的新增内容。整体看，市场讨论集中在 AI 资产的定价与资本开支节奏上，分歧不在方向，而在时点与证据。", "paragraphs": [{"h": "一、市场情绪：龙头回落，板块未同步出清", "text": "NVDA 因一份新报告称 SEC 正在调查其潜在会计问题，单日下跌超过 **12%**，一家市值 **5 万亿美元**以上的公司几周内跌幅达 **46%** 以上，连带冲击主要指数。但板块内部并未同步调整：在 Omer Cheema 跟踪的半导体公司中，**只有 NVDA 接近 52 周低点**，多数低质量公司仍高出 **2 至 4 倍**。值得注意的两点：其一，SEC 调查目前仅有单一来源转述，未见官方确认；其二，龙头调整与板块滞涨同时存在，说明资金尚未系统性撤离。", "refs": [["aleabitoreddit", "2123878986686333308"], ["Omercheema", "2123076524861432038"]]}, {"h": "二、一级市场：发行端与二级情绪出现背离", "text": "Anthropic（$ANT）IPO 的卖方评级清一色为买入，但 Felix Wang 统计的投资者交流中，**58% 为看空或中性、42% 看多**，卖方与买方判断存在明显落差。Ornn 提出的问题更接近本质：Anthropic **8,950 亿美元**的算力支出，将以何种路径在增长与盈利上收回。发行端的乐观与买方的谨慎并存，是本轮 AI 资产定价中较值得跟踪的一组矛盾。", "refs": [["HedgeyeTech", "2123625335547998476"], ["OrnnExchange", "2123811370357690494"]]}, {"h": "三、产业动态：车用半导体的份额正在迁移", "text": "据 SemiAnalysis，高通九月季度车用收入首次接近 **20 亿美元**（年化约 80 亿美元），逼近英飞凌的 **24.5 亿美元**与 NXP 的 **20.7 亿美元**。2016 年高通拟以 470 亿美元收购 NXP 时，对方车用业务规模为其 **8.6 倍**，至上个季度该比值已降至 **1.04 倍**。其增长并非来自整车销量——全球轻型车产量自 2023 年以来基本持平——而是来自单车价值量：由 2022 年的约 **21 美元**升至 2026 年预计的 **76 美元**。", "refs": [["SemiAnalysis_", "2124337151659651116"], ["SemiAnalysis_", "2124337154021101665"], ["SemiAnalysis_", "2124337156546080779"]]}, {"h": "四、资本开支：2027 年拐点的正反证据", "text": "Freda Duan 引述腾讯 Martin Lau 的判断，认为 AI 资本开支将在 **2026-27 年见顶**，理由包括投入前置、2028 年硬件成本下降以及效率提升。与此相对，Ornn 从资产端提出不同看法：H100 与 B200、B300、GB300 的**二手市场价格正在跑赢账面价值**，五年折旧假设可能偏保守。两者讨论的并非同一问题——前者是需求节奏，后者是资产残值，但共同指向同一个变量：算力投入的回收周期。", "refs": [["FredaDuan", "2123088477868736729"], ["OrnnExchange", "2123451571451167047"]]}, {"h": "五、政策与外部变量", "text": "Felix Wang 判断**台湾是最后一个破裂的 AI 泡沫**，并自述在存储板块持有空头；同日，DayOne 的数据中心 IPO 被搁置，反映一级市场融资环境的变化。政策层面，Just Another Pod Guy 的一篇旧帖提出，关税的目标并非贸易平衡，而是迫使盟友停止对华贸易，并明确说明该表述系其对掌权者意图的推断，而非其本人主张。", "refs": [["HedgeyeTech", "2123731560537149580"], ["HedgeyeTech", "2123725033272951075"]]}, {"h": "六、后续观察", "text": "综合来看，本期材料尚不足以形成方向性结论，但留下三个可被后续数据检验的问题：一是 **2027 年前 AI 资本开支是否真的见顶**；二是 **GPU 二手价格能否继续支撑当前的折旧假设**；三是 **Anthropic 的 IPO 定价与二级市场情绪，最终由哪一侧向另一侧收敛**。三条均需等待财报、发行结果或下一轮产业调研验证。", "refs": [["FredaDuan", "2123088477868736729"], ["OrnnExchange", "2123451571451167047"], ["HedgeyeTech", "2123625335547998476"]]}], "note": "短评由编辑基于当日抓取内容撰写，每段后标注来源；文中数字均由脚本回查原文核对。本看板仅做信息整理，不构成投资建议。"};
const DATA=[{"id": "v9", "themes": ["公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["NVDA"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 2220, "r": 118, "url": "https://x.com/aleabitoreddit/status/2123878986686333308", "en": "$NVDA drops over -12%+, from a new report that the SEC is probing potential accounting issues at Nvidia.\n\nAt this point, the collateral damage is starting to hit major indexes and retirement portfolios.\n\nIt's just wild to witness a $5T+ company crash -46%+ in weeks.", "zh": "$NVDA 下跌超过 12%，起因是一份新报告称 SEC 正在调查英伟达潜在的会计问题。\n\n到这个地步，连带损伤已经开始冲击主要指数和退休投资组合。\n\n眼睁睁看着一家市值 5 万亿美元以上的公司几周内暴跌 46% 以上，实在令人错愕。"}]}, {"id": "v8", "themes": ["公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["ANT"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-20", "l": 35, "r": 1, "url": "https://x.com/HedgeyeTech/status/2123625335547998476", "en": "As usual, only buy ratings on $ANT from sell-side. From my investors' conversations, I counted 58% bearish/neutral and 42% bullish", "zh": "和往常一样，卖方对 $ANT 只有买入评级。从我近期与投资者的交流中统计：58% 的人看空或中性，42% 看多。"}, {"u": "HedgeyeTech", "t": "11-18", "l": 68, "r": 5, "url": "https://x.com/HedgeyeTech/status/2123035493226975431", "en": "Today is my perspective on the $ANT IPO. I think investors have seen enough S-1 presentations, so I'm tackling Anthropic a bit differently – particularly from an AI infrastructure lens along with our robust data on global LLMs (1,130 models), conspiracy theories linking $NVDA to $ANT and my thoughts on the new BIS rule.\n\nAlso, I want to highlight two developments that we were probably the first research firm to recognize:\n\n1) June 2026 - Shorted Zai 2513.HK (China's Anthropic); warned clients on distillation loopholes from $ANT and #OpenAI, and global price war\n\n2) July 2026 - Anthropic momentum peaked according to our checks; OpenAI resurgence; removed MSFT Short\n\n（原文末尾另附完整标的清单，共 30 余个，涵盖 AI 基础设施、模型公司与中国互联网资产。）", "zh": "今天谈谈我对 $ANT IPO 的看法。我认为投资者已经看够了 S-1 路演，所以我换一种方式拆解 Anthropic——特别是从 AI 基础设施的角度，结合我们关于全球大模型（1,130 个模型）的扎实数据、把 $NVDA 与 $ANT 联系起来的各种阴谋论，以及我对新 BIS 规则的看法。\n\n另外，我想强调两个进展——我们可能是最早识别出它们的研究机构：\n\n1）2026 年 6 月——做空 Zai（2513.HK，中国的 Anthropic）；就 $ANT 与 OpenAI 之间的蒸馏漏洞和全球价格战向客户发出警告。\n\n2）2026 年 7 月——根据我们的调研，Anthropic 的增长动能已见顶；OpenAI 复苏；平掉微软空头。\n\n（原文末尾另附完整标的清单，共 30 余个，涵盖 AI 基础设施、模型公司与中国互联网资产。）"}]}, {"id": "v2", "themes": ["行业"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-20", "l": 48, "r": 6, "url": "https://x.com/HedgeyeTech/status/2123731560537149580", "en": "Taiwan was the last AI bubble to pop. We have a memory Short there", "zh": "台湾是最后一个破裂的 AI 泡沫。我们在存储板块持有一个空头仓位。"}]}, {"id": "v1", "themes": ["行业"], "date": "2026-11-22", "time": "11-22", "tickers": ["QCOM"], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-22", "l": 217, "r": 23, "url": "https://x.com/SemiAnalysis_/status/2124337151659651116", "en": "Is Qualcomm going to be the largest automotive semiconductor company in 2027? We think so. It’s a story the market has quietly ignored.\nIn the September quarter, Qualcomm hit nearly $2B in quarterly auto revenue for the first time ($8B annual run rate), closing in on Infineon at $2.45B and NXP at $2.07B. Qualcomm has already overtaken traditional auto semi companies such as TI, STMicro, Renesas, Analog Devices and onsemi. (1/7)", "zh": "高通会在 2027 年成为最大的车用半导体公司吗？我们认为会。这是一个被市场安静忽略的故事。\n\n在九月季度，高通的车用业务收入首次接近 20 亿美元（年化约 80 亿美元），逼近英飞凌的 24.5 亿美元和 NXP 的 20.7 亿美元。高通已经超越了 TI、意法半导体、瑞萨、ADI 和安森美等传统车用半导体公司。（1/7）"}, {"u": "SemiAnalysis_", "t": "11-22", "l": null, "r": null, "url": "https://x.com/SemiAnalysis_/status/2124337154021101665", "en": "Back in Oct-2016, when Qualcomm tried to buy NXP for $47B, NXP’s auto business was 8.6x the size of Qualcomm’s. Last quarter that ratio was down to 1.04x.\nEven without the NXP deal, Qualcomm went past Analog Devices in 2Q24, onsemi in 1Q25, Renesas in 4Q25, STMicro in 1Q26 and Texas Instruments in 3Q26 (by our estimate). (2/7)", "zh": "回到 2016 年 10 月，高通试图以 470 亿美元收购 NXP 时，NXP 的车用业务规模是高通的 8.6 倍。上个季度，这个比值已经降到 1.04 倍。\n\n即便没有这桩收购，高通也先后超过了 ADI（2024 年二季度）、安森美（2025 年一季度）、瑞萨（2025 年四季度）、意法半导体（2026 年一季度），以及德州仪器（2026 年三季度，按我们估算）。（2/7）"}, {"u": "SemiAnalysis_", "t": "11-22", "l": null, "r": null, "url": "https://x.com/SemiAnalysis_/status/2124337156546080779", "en": "Global light-vehicle production has stayed relatively flat since 2023, yet Qualcomm’s auto revenue per car is up 3.7x from 2022 to 2026E (about $21 to $76). Its auto semi growth story is decoupled from vehicle units and primarily driven by content gains. (3/7)", "zh": "自 2023 年以来，全球轻型车产量基本持平，但高通的单车车用收入从 2022 到 2026 年预计增长 3.7 倍（约从 21 美元升到 76 美元）。它的车用半导体增长与整车销量脱钩，主要由单车价值量提升驱动。（3/7）"}, {"u": "SemiAnalysis_", "t": "11-22", "l": null, "r": null, "url": "https://x.com/SemiAnalysis_/status/2124337159041695804", "en": "Qualcomm has beaten every auto target it has set. It guided $1.5B for fiscal 2024 and did $2.9B, guided $3.5B for fiscal 2026 and did $6.0B, and exited the year at an $8.0B annual rate five years ahead of its old fiscal 2031 goal.\nQualcomm targets $10B in auto semi revenue by fiscal 2029. If Infineon grows about 10% a year after fiscal 2027 as its CEO expects, it will reach roughly $12.4B, so Qualcomm will need to beat its target by about 25% to hold #1. (4/7)", "zh": "高通每一个车用目标都超额完成：2024 财年指引 15 亿美元、实际 29 亿；2026 财年指引 35 亿、实际 60 亿；并以 80 亿美元的年化收入收官，比原定 2031 财年目标提前了五年。\n\n高通目标 2029 财年车用半导体收入达 100 亿美元。若英飞凌按其 CEO 预期在 2027 财年后保持约 10% 年增长，将做到约 124 亿美元——高通需要超额完成目标约 25% 才能保住第一。（4/7）"}, {"u": "SemiAnalysis_", "t": "11-22", "l": null, "r": null, "url": "https://x.com/SemiAnalysis_/status/2124337161105195142", "en": "Qualcomm’s design-win pipeline grew 22x from $3B in early 2018 to $65B in Jun-2026, more than 2.6x Mobileye’s $24.5B pipeline.\nDriver assistance (ADAS) was already about a third of the pipeline in 2024, and BMW and Stellantis have since picked Qualcomm for central compute and driving software. Those programs start ramping in 2027 and 2028 on top of early Chinese cockpit scale. (5/7)", "zh": "高通的设计中标管线从 2018 年初的 30 亿美元增长 22 倍，到 2026 年 6 月达 650 亿美元，是 Mobileye 245 亿美元管线的 2.6 倍以上。\n\n2024 年时 ADAS 已约占管线三分之一；此后宝马和 Stellantis 又选择高通做中央计算与驾驶软件，这些项目将在 2027、2028 年放量，叠加早期中国座舱业务的规模。（5/7）"}, {"u": "SemiAnalysis_", "t": "11-22", "l": null, "r": null, "url": "https://x.com/SemiAnalysis_/status/2124337163357610272", "en": "Qualcomm sidestepped traditional competitors like Infineon, NXP and TI in power chips, microcontrollers, analog and sensors. It went straight after digital cockpit, ADAS and connectivity, buying Arriver (2022) for ADAS software and Autotalks (2025) for V2X safety chips to offer a complete hardware-and-software platform.\nThat compute and connectivity business grew 89% from a year ago at Qualcomm last quarter, while Infineon and NXP grew 10% to 13%. (6/7)", "zh": "高通绕开了英飞凌、NXP、TI 在电源芯片、微控制器、模拟和传感器上的正面竞争，直接切入数字座舱、ADAS 和连接，并通过收购 Arriver（2022 年，ADAS 软件）和 Autotalks（2025 年，V2X 安全芯片）提供完整的软硬件平台。\n\n上季度这块计算与连接业务同比增长 89%，而英飞凌和 NXP 只增长 10%–13%。（6/7）"}, {"u": "SemiAnalysis_", "t": "11-22", "l": null, "r": null, "url": "https://x.com/SemiAnalysis_/status/2124337165437960410", "en": "Passing Infineon in 2027 comes down to quarterly math and FX. Infineon guided fiscal 2027 Automotive up mid-teens to roughly $10.3B at 1.15 EUR/USD (helped by moving onboard chargers into the segment), and both companies guided the December quarter flat.\n\nAt 12% quarterly growth next year (half its recent 20% to 25% pace), Qualcomm passes NXP in 1Q27, overtakes Infineon on quarterly revenue in 3Q27 ($2.80B vs $2.68B), and wins calendar 2027 ($10.7B vs $10.5B). Winning fiscal 2027 takes 17.5% quarterly growth after December. (7/7)", "zh": "2027 年能否超过英飞凌，取决于季度数据和汇率。英飞凌指引 2027 财年车用业务中双位数增长，按 1.15 欧元/美元约 103 亿美元，两家公司对 12 月季度的指引都是持平。\n\n若明年保持 12% 的季度环比增长（约为近期 20%–25% 增速的一半），高通将在 2027 年一季度超过 NXP，三季度在季度收入上超过英飞凌（28.0 亿 vs 26.8 亿美元），并在 2027 日历年胜出（107 亿 vs 105 亿美元）。若要在 2027 财年就胜出，12 月之后需要 17.5% 的季度增速。（7/7）"}]}, {"id": "v3", "themes": ["行业"], "date": "2026-11-19", "time": "11-19", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-19", "l": 43, "r": 8, "url": "https://x.com/OrnnExchange/status/2123451571451167047", "en": "Are five-year depreciation schedules too pessimistic on GPU residual values?\n\nAccording to Ornn Data, secondary market prices for the older H100 and the newer B200, B300 and GB300 are outpacing book value.\n\nFor lenders, these GPUs continue earning rental revenue while their resale value holds or rises, making them stronger collateral than a standard five-year schedule assumes.", "zh": "五年折旧安排对 GPU 残值来说是不是过于悲观了？\n\n根据 Ornn 的数据，较老的 H100 与较新的 B200、B300、GB300 的二手市场价格正在跑赢账面价值。\n\n对放贷方而言，这些 GPU 在继续产生租赁收入的同时，转售价值还能持平甚至上升——这使它们成为比标准五年折旧假设更强的抵押品。"}]}, {"id": "v4", "themes": ["公司", "行业"], "date": "2026-11-20", "time": "11-20", "tickers": ["ANT"], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-20", "l": 22, "r": 1, "url": "https://x.com/OrnnExchange/status/2123811370357690494", "en": "How does Anthropic's $895 Billion in compute spend pay off for its growth trajectory and path to profitability? Dario Amodei weighs in with CNBC.\n\nRead our research for more breakdown.", "zh": "Anthropic 8,950 亿美元的算力支出，如何在其增长轨迹和盈利路径上收回？Dario Amodei 在 CNBC 上给出了看法。\n\n更多拆解请阅读我们的研究。"}]}, {"id": "v5", "themes": ["行业", "公司"], "date": "2026-11-18", "time": "11-18", "tickers": ["NVDA"], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-18", "l": 38, "r": 4, "url": "https://x.com/Omercheema/status/2123076524861432038", "en": "Among all semis on my tracker, Only NVDA is trading close to its 52 week low. Many low quality companies are still 2x or even 4x higher. AMS, AEHR, WOLF, SIVE, AAOI to name a few.", "zh": "在我跟踪的所有半导体公司里，只有 NVDA 的交易价格接近 52 周低点。许多低质量公司仍然高出 2 倍甚至 4 倍——AMS、AEHR、WOLF、SIVE、AAOI 等等。"}]}, {"id": "v7", "themes": ["公司"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-20", "l": 30, "r": 2, "url": "https://x.com/HedgeyeTech/status/2123725033272951075", "en": "DayOne (data center IPO) put on hold", "zh": "DayOne（数据中心相关 IPO）被搁置。"}]}, {"id": "v10", "themes": ["行业", "公司"], "date": "2026-11-18", "time": "11-18", "tickers": ["TCEHY"], "accounts": ["FredaDuan"], "tweets": [{"u": "FredaDuan", "t": "11-18", "l": 165, "r": 28, "url": "https://x.com/FredaDuan/status/2123088477868736729", "en": "$Tencent / Chinese CSPs' tone on the AI capex cycle is very clear -\n\nMartin Lau laid out a clear case for why AI capex should moderate after 2027:\n\n1/ Front-loaded investment: AI infrastructure is like building a factory. Once built, it can continuously train new models and generate tokens.\n\n2/ Lower hardware costs: The same equipment should cost significantly less by 2028.\n\n3/ Rapid efficiency gains: The same infrastructure can deliver exponentially more training compute and token output over time.\n\nTakeaway: Martin is effectively calling for a peak in AI capex in 2026-27, with a meaningful decline in capex intensity thereafter, even as AI demand continues to grow.\n\nThe read-through for semis is interesting: If annual industry AI capex eventually normalizes below $1T, assigning a mid-range multiple to normalized earnings, that's your industry total size.", "zh": "$Tencent / 中国云厂商对 AI 资本开支周期的口风非常清楚——\n\nMartin Lau 给出了 AI 资本开支应在 2027 年后放缓的明确理由：\n\n1/ 前置投资：AI 基础设施就像建工厂。一旦建成，就可以持续训练新模型、产出 token。\n\n2/ 硬件成本下降：到 2028 年，同样的设备成本应该会低得多。\n\n3/ 效率快速提升：同样的基础设施，随着时间推移可以输出指数级更多的训练算力和 token。\n\n结论：Martin 实际上是在说 AI 资本开支将在 2026-27 年见顶，此后资本开支强度会明显回落，即使 AI 需求仍在增长。\n\n对半导体的传导很有意思：如果行业年度 AI 资本开支最终常态化到 1 万亿美元以下，再给常态化盈利一个中位数估值倍数，那就是这个行业的总规模。"}]}, {"id": "v12", "themes": ["行业", "公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["ANT"], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-20", "l": 17, "r": 0, "lang": "zh", "url": "https://x.com/RYANHINGSHING/status/2123787556626321770", "en": "按道理Ant上市會抽走流動性，同時vol上升會令半導體股大跌，今次是retest低位\n\n但我猜Ant……\n\n（此推文為訂閱者專屬內容，X 僅顯示預覽）", "zh": "按理说，Ant 上市会抽走流动性，同时波动率上升会让半导体股大跌，这次是回踩低位。\n\n但我猜 Ant……\n\n（作者设置了「订阅者专属」，完整内容需订阅才能查看，以上为 X 公开显示的预览）"}]}, {"id": "v13", "themes": ["行业"], "date": "2026-11-19", "time": "11-19", "tickers": [], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-19", "l": 12, "r": 0, "lang": "zh", "url": "https://x.com/RYANHINGSHING/status/2123401758194184292", "en": "最近一直在研究模型公司，因為這些公司對semi影響很大\n\n中國AI模型公司似乎把戰略投向Pro，應該……\n\n（此推文為訂閱者專屬內容，X 僅顯示預覽）", "zh": "最近一直在研究模型公司，因为这些公司对半导体影响很大。\n\n中国 AI 模型公司似乎把战略转向 Pro，应该……\n\n（作者设置了「订阅者专属」，完整内容需订阅才能查看，以上为 X 公开显示的预览）"}]}, {"id": "n1", "themes": ["行业", "公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["ORCL", "SNDK", "CRWV"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 618, "r": 39, "url": "https://x.com/i/status/2124315829202493468", "en": "It's very interesting \n$ORCL\n can put out statements about being fully funded for OpenAI.\n\nOr \n$SNDK\n / Micron can put out statements reassuring investors about signed LTAs + price floors. \n\nYet there's extraordinary levels of distrust toward disclosures and durability. \n\nEither everyone is excessively bearish, and this creates a generational buying opportunity on AI if contracts + projections hold... or they're skeptical for a good reason.", "zh": "$ORCL 能发布声明称已为 OpenAI 提供全额资金，这非常有意思。或者 $SNDK / 美光能发布声明，用已签署的长期协议 + 价格下限来安抚投资者。然而，市场对这些披露和持久性的不信任程度极高。要么所有人都过度看空，如果合同和预测成立，这将创造一代人一次的 AI 买入机会……要么他们怀疑是有充分理由的。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 49, "r": 3, "url": "https://x.com/i/status/2124318494879780986", "en": "Maybe it's self-fufilling, we'll see. From earnings, \n$CRWV\n said 10x quantified demand > compute availability throughout 2027.\n\nThen the same week a bunch of people are arguing for a compute glut extrapolating smaller Asian DCs getting impacted. \n\nOne of the most interesting market dynamics", "zh": "也许这是自我实现的，我们拭目以待。从财报看，$CRWV 表示到 2027 年全年，量化需求是算力可用性的 10 倍。然后同一周，一群人却在主张算力过剩，并外推亚洲较小数据中心受到影响。这是最有趣的市场动态之一。"}]}, {"id": "n2", "themes": ["行业", "宏观"], "date": "2026-11-20", "time": "11-20", "tickers": ["AMZN", "SPCX"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 378, "r": 16, "url": "https://x.com/i/status/2123851594811011470", "en": "I covered this earlier in Jan regarding PCB bottlenecks with photonics + \n$AMZN\n Kuiper / \n$SPCX\n starlink supply chains.\n\nBut as an update, it like other industries outside of AI are really starting to feel the pain now too.  \n\nGlobal Electronics Association: \"Is issuing this Industry Alert on escalating shortages across the printed circuit board (PCB) supply chain. \n\nCompanies in automotive, industrial, medical, defense, and telecommunications report longer lead times and difficulty securing supply as AI absorbs scarce capacity, effectively putting production at risk\"\n\nThe association meaningful relief unlikely before mid-2028. The association urged buyers to plan ahead for supply constraints and manufacturers.\n\nHyperscalers like \n$AMZN\n already planned ahead of time taking stakes in Gold Circuit Electronics (2368) for supply procurement... \n\nBut can't say the same about other industries procurement (medical industry is probably not used to competing with hyperscalers over the same supply lol). \n\nThe resulting shortages of critical materials, including CCLs and fibreglass cloth, are squeezing supplies for consumer electronics.\n\nTLDR: same bottleneck, same timeline for 2028. It's just interesting to see association warnings about it impacting medical to defense industries. \n\nSo there's incremental information that it's become an industry wide allocation issue. \n\nI also think it's helpful to see escalating shortages + broadening... so it might show the selloff is starting to look very disconnected with fundamental demand.", "zh": "我在1月份早些时候就报道过PCB瓶颈与光子学+ $AMZN Kuiper / $SPCX 星链供应链的问题。\n\n但作为更新，它和AI以外的其他行业一样，现在也真的开始感受到痛苦了。\n\n全球电子协会：“就印刷电路板（PCB）供应链日益加剧的短缺发布此行业警报。\n\n汽车、工业、医疗、国防和电信行业的公司报告称，随着AI吸收稀缺产能，交货时间延长且难以确保供应，实际上使生产面临风险”\n\n该协会表示，在2028年中期之前不太可能有实质性的缓解。该协会敦促买家提前规划供应限制和制造商。\n\n像 $AMZN 这样的超大规模企业已经提前规划，入股Gold Circuit Electronics（2368）以确保供应采购……\n\n但不能说其他行业的采购也是如此（医疗行业可能不习惯与超大规模企业在同一供应上竞争，哈哈）。\n\n由此产生的关键材料短缺，包括CCL和玻璃纤维布，正在挤压消费电子产品的供应。\n\nTLDR：同样的瓶颈，2028年的同样时间线。看到协会警告其影响从医疗到国防行业，这很有趣。\n\n因此有增量信息表明，这已成为一个全行业范围的分配问题。\n\n我还认为，看到短缺加剧+范围扩大是有帮助的……因此这可能表明抛售开始看起来与基本面需求非常脱节。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 71, "r": null, "url": "https://x.com/i/status/2123859267560304947", "en": "Thanks, I'll try to make more higher signal fundamental posts. I tend to post more random stuff when I'm stressed (especially with the broader market crash)\n\nBut it is pretty wild to see the disconnect between supply procurement patterns and valuations during this deleveraging period.", "zh": "但更新一下，像其他非AI行业现在也开始真正感受到痛苦了。"}]}, {"id": "n3", "themes": ["宏观", "行业"], "date": "2026-11-20", "time": "11-20", "tickers": ["CRWV"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 1300, "r": 68, "url": "https://x.com/i/status/2123841418577973727", "en": "> Democrats: \"Let's ban new datacenters in the US\"\n> Trump: \"Let's ban new datacenters overseas\"\n> \n$CRWV\n: ???", "zh": "民主党人：“让我们在美国禁止新建数据中心”\n特朗普：“让我们在海外禁止新建数据中心”\n$CRWV：？？？"}, {"u": "aleabitoreddit", "t": "11-20", "l": 63, "r": null, "url": "https://x.com/i/status/2123842606820135371", "en": "It's much more nuanced than that, I'm just making a joke. DC developers will find ways to get it done.\n\nIt's just statements from Trump like this introduce unnecessary uncertainty.", "zh": "实际情况要微妙得多，我只是开个玩笑。数据中心开发商总会找到办法完成建设。\n只是特朗普这样的表态引入了不必要的不确定性。"}]}, {"id": "n4", "themes": ["宏观", "公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["HOOD", "NBIS"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 1700, "r": 93, "url": "https://x.com/i/status/2123805601411277149", "en": "Feels like every growth equity, even outside of AI, from \n$HOOD\n to \n$NBIS\n has fallen off a cliff.\n\nMeanwhile bubbles are forming in consumer staples, with valuations not seen since 1999.\n\nDo you guys think markets are right... that premiums given to rocket or AI companies, should be given to towel resellers like Walmart instead?", "zh": "感觉所有成长型股票，即便不属于AI领域，从$HOOD到$NBIS，都像是跌下了悬崖。\n\n与此同时，消费必需品领域正在形成泡沫，估值达到了自1999年以来未见的高度。\n\n你们认为市场是对的……即给予火箭或AI公司的溢价，应该转而给予像沃尔玛这样的毛巾销售商吗？"}]}, {"id": "n5", "themes": ["公司"], "date": "2026-11-21", "time": "11-21", "tickers": ["NVDA", "AMD"], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-21", "l": 791, "r": 49, "url": "https://x.com/i/status/2124267194267652470", "en": "BREAKING: Jensen Huang reportedly told NVIDIA employees that if AMD's Minimax Inferact kernels beat NVIDIA's on AgentX performance targets, he would reset every NVIDIA employee's GTA 6 progress.\n\nThe employees then broke down crying. Jensen called it \"high-performance levers of motivation.\"\n\nIs this the kind of thing you want to see from the leader of one of the largest companies on Earth? Disgusting. (Source: roommate)", "zh": "突发：据报道，黄仁勋对NVIDIA员工表示，如果AMD的Minimax Inferact内核在AgentX性能目标上击败NVIDIA，他将重置每位NVIDIA员工的GTA 6进度。\n\n员工们随后痛哭失声。黄仁勋称之为“高性能激励杠杆”。\n\n这是你想从地球上最大公司之一的领导者身上看到的事情吗？令人作呕。（来源：室友）"}]}, {"id": "n6", "themes": ["宏观"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-20", "l": 25, "r": 1, "url": "https://x.com/i/status/2123862479683899849", "en": "Is it going to be a V shaped recovery or U shaped? Discuss", "zh": "这会是V型复苏还是U型复苏？请讨论"}]}, {"id": "n7", "themes": ["宏观"], "date": "2026-11-19", "time": "11-19", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-19", "l": 17, "r": 1, "url": "https://x.com/i/status/2123487859201991037", "en": "1.x trillion market cap  in 5 years. Amazing achievement.", "zh": "五年内市值达到1.x万亿美元。惊人的成就。"}, {"u": "Omercheema", "t": "11-19", "l": 28, "r": 1, "url": "https://x.com/i/status/2123352600783225261", "en": "In 1990s, shortly after the Soviet Union collapsed, a Russian official responsible for bread production visited London. Standing in shops stocked with fresh loaves of every variety, he asked his British hosts: who was in charge of the bread supply for the entire city?\n\nThe answer “nobody” left him stunned. In the Soviet Union,  Prices were fixed by the state, production was planned by committees, and shortages were managed through queues and rationing. Officials spent endless hours calculating how many loaves should be baked each day, yet the result was frequently too little, too much, or the wrong kind. \n\nIn London there was no central bakery directorate, no daily conference of factory managers reporting to a ministry, and no price controls on the staple. Farmers, millers, bakers, and retailers simply competed. Each sought a profit; none coordinated by decree. The outcome was abundant, varied, and relatively inexpensive bread available on demand. The official could not immediately accept that this unplanned coordination, driven by price signals rather than commands, had solved a problem that central planning had never mastered.\n\nCapitalism works. Healthy competition works. Unhealthy barriers to competition don't.", "zh": "上世纪90年代，苏联解体后不久，一位负责面包生产的俄罗斯官员访问了伦敦。站在摆满各种新鲜面包的商店里，他问英国东道主：谁负责整个城市的面包供应？\n\n“没有人”这个回答让他震惊。在苏联，价格由国家固定，生产由委员会计划，短缺通过排队和配给来管理。官员们花费无数时间计算每天应该烤多少面包，但结果常常是太少、太多或种类不对。\n\n在伦敦，没有中央面包管理局，没有工厂经理每天向部委汇报的会议，也没有对主食的价格控制。农民、磨坊主、面包师和零售商只是相互竞争。每个人都追求利润；没有人靠法令协调。结果是充足、多样且相对便宜的面包随需可得。这位官员无法立即接受，这种由价格信号而非命令驱动的无计划协调，解决了一个中央计划从未掌握的问题。\n\n资本主义行之有效。健康的竞争行之有效。不健康的竞争壁垒则不然。"}]}, {"id": "n8", "themes": ["宏观"], "date": "2026-11-19", "time": "11-19", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-19", "l": 20, "r": null, "url": "https://x.com/i/status/2123408274623975710", "en": "Happy Anthropic Day. \n\nMay Lakshmi devi bless you all.", "zh": "人类学日快乐。愿拉克希米女神保佑你们所有人。"}]}, {"id": "n9", "themes": ["宏观"], "date": "2026-11-18", "time": "11-18", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-18", "l": 17, "r": 1, "url": "https://x.com/i/status/2123353742871310697", "en": "Nobody knows the future. Nothing wrong with revisiting estimates. Analysts do it wll the time.", "zh": "没人知道未来。重新审视估算没有错。分析师们一直这么做。"}, {"u": "Omercheema", "t": "11-18", "l": null, "r": null, "url": "https://x.com/i/status/2123434160891089373", "en": "Yes. ", "zh": "是的。"}]}, {"id": "n10", "themes": ["行业"], "date": "2026-11-21", "time": "11-21", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-21", "l": 57, "r": 7, "url": "https://x.com/i/status/2124177379773894895", "en": "\"Compute beats oil.\"\n\nOur co-founder & CEO \n@Bavaria_kush\n sat down with \n@HarryStebbings\n on \n@20VC\n to talk about the state of compute and AI.\n\nWatch the full episode: \nhttps://\nyoutu.be/3ZkDiDrxDeY", "zh": "算力胜过石油。"}]}, {"id": "n11", "themes": ["行业"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-20", "l": 55, "r": 4, "url": "https://x.com/i/status/2123600228452360484", "en": "Jevons paradox in one chart: tokens get cheaper, demand explodes, compute gets pricier. \n\nWe track both, every day on Ornn Data.", "zh": "一张图看懂杰文斯悖论：代币越来越便宜，需求爆炸式增长，算力却越来越贵。"}]}, {"id": "n12", "themes": ["行业"], "date": "2026-11-18", "time": "11-18", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-18", "l": 81, "r": 8, "url": "https://x.com/i/status/2123076265359851737", "en": "Ornn has launched Historical Forward Curves, showing historical trends in long-term compute contracts from A100 to GB300.\n\nMature markets like oil and natural gas have long tracked the history of their forward curves to benchmark prices and manage term risk. Compute now has this history too, exclusively on Ornn Data.\n\nSet any GPU’s curve to a past date, or pin several dates and compare them on one chart, to see how prices moved before you lock a contract.\n\nExplore the curves → \nhttp://\ndata.ornn.com/analytics", "zh": "Ornn 已推出历史远期曲线，展示从 A100 到 GB300 的长期算力合约的历史趋势。\n\n像石油和天然气这样的成熟市场长期以来一直追踪其远期曲线的历史，以对标价格并管理期限风险。算力现在也有了这样的历史，独家收录于 Ornn Data。\n\n将任意 GPU 的曲线设定到过去的某个日期，或固定多个日期并在同一张图表上进行比较，以便在锁定合约之前查看价格是如何变动的。\n\n探索这些曲线 → \nhttp://\ndata.ornn.com/analytics"}]}, {"id": "n14", "themes": ["宏观", "行业"], "date": "2026-11-20", "time": "11-20", "tickers": ["QQQ"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-20", "l": 75, "r": 2, "url": "https://x.com/i/status/2123732732505444862", "en": "Tough spot for tech right now. With an increasingly uncertain 2027 for tech, “cheap” valuations could get cheaper as estimates get cut. On the other hand, I’m looking into more insulated plays that may  withstand AI downturns  \n$QQQ", "zh": "科技板块目前处境艰难。随着2027年科技行业前景日益不确定，\"便宜\"的估值可能因盈利预期被下调而变得更便宜。另一方面，我正在研究一些更具防御性、可能抵御AI下行的标的 $QQQ"}]}, {"id": "n15", "themes": ["宏观", "行业"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-20", "l": 57, "r": 3, "url": "https://x.com/i/status/2123607705969401895", "en": "AI trade plummeting - Korea, Japan and Taiwan indexes all down 5% overnight.", "zh": "AI 交易大幅下挫——韩国、日本和台湾股指隔夜均下跌 5%。"}]}, {"id": "n17", "themes": ["行业"], "date": "2026-11-19", "time": "11-19", "tickers": ["AMD", "NVDA"], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-19", "l": 14, "r": null, "url": "https://x.com/i/status/2123467229903901160", "en": "You don’t say…\n\nWhy do you expect that \n$AMD\n doesn’t sell chips in China when \n$NVDA\n sells lots of chips in China?", "zh": "可不是嘛……"}, {"u": "RYANHINGSHING", "t": "11-19", "l": 4, "r": null, "url": "https://x.com/i/status/2124023634436235372", "en": "壽司郎太多人排隊了\n\n事已至此，去食海南雞飯\n\n@on8482669519610\n  \nhttps://\nx.com/on848266951961\n/on8482669519610/status/2124023634436235372\n…", "zh": "英伟达在中国卖出大量芯片，你凭什么指望AMD不在中国卖芯片？"}]}, {"id": "n18", "themes": ["行业", "行业"], "date": "2026-11-22", "time": "11-22", "tickers": [], "accounts": ["FredaDuan"], "tweets": [{"u": "FredaDuan", "t": "11-22", "l": 85, "r": 11, "url": "https://x.com/i/status/2124325047120900224", "en": "RSI is a powerful deflationary flywheel: compounding gains in token efficiency drive down the compute required to deliver the same level of intelligence. Token consumption, model revenue, and semiconductor demand are three very different things - yet the market often treats them as the same trade.\n\nThe cost of intelligence is already falling at an extraordinary pace.\n\nEpoch AI estimates that the cost of achieving a fixed level of AI capability has declined ~47% per quarter since 2023. Separately, research on model capability density suggests that comparable performance can be delivered with roughly half the parameters every 3.5 months. Capabilities that once required frontier-scale models are increasingly available in much smaller, cheaper models.\n\nRSI could accelerate this trend even further. The faster intelligence improves, the faster it may become cheaper to produce. AI capabilities could advance exponentially without requiring a proportional increase in compute.\n\nThis creates an increasingly demanding hurdle for growth.\n\nAt a 47% quarterly decline in the cost of a fixed level of intelligence, consumption of that intelligence would need to increase ~90% per quarter just to keep the associated revenue flat, all else equal. New use cases and economically valuable workloads must be unlocked fast enough to absorb that deflation.\n\nSo far, demand growth has been extraordinary. OpenRouter processed nearly 25x more tokens in October than in January, while effective token prices fell 57-70% over the same period. But exponential token growth does not automatically translate into exponential revenue growth, let alone sustained growth in semiconductor capex.\n\nFor the past several years, rapid advances in frontier AI, explosive token consumption, and accelerating infrastructure investment have largely reinforced one another.\n\nThere is no guarantee these three curves will continue to move together.\n\nThe next phase of AI will be defined not just by how quickly intelligence improves, but by whether new demand can outrun the deflation that comes with that progress.\n\n—\n\nEpoch AI - The Plunging Price of Thought\n\nhttps://\nepoch.ai/publications/t\nhe-plunging-price-of-thought\n…\n\nNature Machine Intelligence - Densing Law of LLMs\n\nhttps://\nnature.com/articles/s4225\n6-025-01137-0\n…\n\nOpenRouter - October 2026 Data Recap\n\nhttps://\nopenrouter.ai/data/october-2\n026\n…", "zh": "RSI是一个强大的通缩飞轮：代币效率的复合增益推动降低提供同等智能水平所需的算力。代币消耗、模型收入和半导体需求是三件截然不同的事情——然而市场往往将它们视为同一笔交易。\n\n智能的成本已经在以非凡的速度下降。\n\nEpoch AI估计，自2023年以来，实现固定水平AI能力的成本每季度下降约47%。另外，关于模型能力密度的研究表明，大约每3.5个月就可以用大约一半的参数提供可比性能。曾经需要前沿规模模型才能实现的能力，正越来越多地出现在小得多、便宜得多的模型中。\n\nRSI可能会进一步加速这一趋势。智能提升得越快，其生产成本可能下降得越快。AI能力可能会指数级进步，而不需要算力成比例增加。\n\n这为增长创造了一个日益苛刻的门槛。\n\n在固定水平智能的成本每季度下降47%的情况下，其他条件不变时，对这种智能的消耗需要每季度增长约90%，才能仅保持相关收入持平。新的用例和有经济价值的工作负载必须足够快地解锁，以吸收这种通缩。\n\n到目前为止，需求增长非同寻常。OpenRouter在10月处理的代币量几乎是1月的25倍，而同期有效代币价格下降了57-70%。但代币的指数级增长并不会自动转化为收入的指数级增长，更不用说半导体资本支出的持续增长。\n\n过去几年，前沿AI的快速进步、代币消耗的爆炸式增长以及基础设施投资的加速，在很大程度上相互强化。\n\n不能保证这三条曲线会继续一起移动。\n\nAI的下一阶段不仅将由智能提升的速度来定义，还将由新需求能否跑赢伴随这一进步而来的通缩来定义。\n\n—\n\nEpoch AI - 思维价格的暴跌\n\nhttps://\nepoch.ai/publications/t\nhe-plunging-price-of-thought\n…\n\nNature Machine Intelligence - 大语言模型的致密化定律\n\nhttps://\nnature.com/articles/s4225\n6-025-01137-0\n…\n\nOpenRouter - 2026年10月数据回顾\n\nhttps://\nopenrouter.ai/data/october-2\n026\n…"}]}, {"id": "n31", "themes": ["公司", "产业·AI算力"], "date": "2026-10-28", "time": "10-28", "tickers": ["TSLA"], "accounts": ["FredaDuan"], "tweets": [{"u": "FredaDuan", "t": "10-28", "l": 99, "r": 17, "url": "https://x.com/i/status/2115141073538572381", "en": "$TSLA's Latest Austin @robotaxi Week Tops @Waymo's Q2 Avg.\n\nChart h/t RobotaxiTracker \n\n$TSLA Robotaxi's rapid ramp in Austin: 438K driverless miles in the latest reported week, ~3.4x since late Aug. @Waymo 's 406K/week is a Q2 average, assuming that number has also been growing in Q3.\n\nStill a big milestone.\n\nWould love to see paid rides data (and obviously safety data) next.\n\n$TSLA now operates driverless in 6 cities vs. @Waymo's 15. In Texas, registered fleets are already getting close: 970 Tesla (507 Model Ys, 463 @OptimusCybercab) vs. 1,207 Waymo.\n\nStill early, but impressive progress!\n\nCan't wait for try FSD v15! @aelluswamy @pduan", "zh": "$TSLA最新奥斯汀@robotaxi周数据超过@Waymo第二季度平均值。"}]}, {"id": "n32", "themes": ["宏观"], "date": "2026-11-02", "time": "11-02", "tickers": [], "accounts": ["TMTLongShort"], "tweets": [{"u": "TMTLongShort", "t": "11-02", "l": null, "r": 16, "url": "https://x.com/i/status/2117051262885573091", "en": "That’s something people think is true before they meet actual rich people who can pay promoters/model bookers to construct a false status hierarchy around them and surprisingly these DJs act like Star-struck plebs when they’re around billionaires. \n\nFor every reserved prim-and-proper nerd like KG there is a degenerate Turkish billionaire you never heard of who fucks himself to death every night surrounded by models that wouldn’t be caught dead behind a Summit booth.", "zh": "这是人们在遇到真正的富人之前会认为正确的事情，这些富人能付钱给推广者/模特经纪人，在他们周围构建虚假的地位等级，而令人惊讶的是，这些DJ在亿万富翁身边时表现得像追星的平民。"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": 0, "url": "https://x.com/i/status/2117057221888782538", "en": "I should clarify that for most billionaires this is generally unappealing and frowned upon.  But that’s doesn’t change the fact that it’s an option for anyone who has enough money to pay for promoters.  It’s just that the avg age of a billionaire is 50+", "zh": "对于每一个像KG这样矜持正经的书呆子，都有一个你从未听说过的堕落的土耳其亿万富翁，他每晚在模特环绕中纵欲至死，而那些模特绝不会出现在Summit展台后面。"}]}, {"id": "n33", "themes": ["公司"], "date": "2026-11-02", "time": "11-02", "tickers": [], "accounts": ["TMTLongShort"], "tweets": [{"u": "TMTLongShort", "t": "11-02", "l": null, "r": 62, "url": "https://x.com/i/status/2116981066380796409", "en": "The problem and beauty of this site is there is an abundance of anons who have a false sense of superiority because they have been surrounded by intellectual mids their whole life and therefore assume that because they landed themselves a “prestigious” seat on the buyside or at an ivy they must be extraordinary. \n\nThe difference between someone of Shaun’s intellectual caliber and the median buysider is wider than the difference between the median buysider and the most retarded kid in their high school class.  \n\nIt’s just that in polite company truly gifted people downplay their abilities while most of fintwit has grown up clinging to their intellectual superiority vs the masses as their entire identity.  \n\nAnd yes I am just as guilty…people who live in a glass house shouldn’t throw stones and all that… but the point still stands that like I’ve said before 99% of people at the ostensibly most prestigious funds are at least an SD less equipped intellectually vs Shaun or core researchers at AI labs.  \n\nIt’s just your social environment has insulated you from this reality by upping the perceived value of modeling with precision while hopped up on adderall while under emphasizing the fact that divergent thinking is exponentially more conducive to generating alpha.", "zh": "这个网站的问题和美妙之处在于，有大量匿名用户有一种虚假的优越感，因为他们一生都被智力中等的人包围，因此认为自己在买方或常春藤获得了一个“ prestigious”的席位，就一定是非凡的。Shaun 的智力水平与买方中位数之间的差距，比买方中位数与他们高中班级里最迟钝的孩子之间的差距还要大。只是在礼貌的场合，真正有天赋的人会淡化自己的能力，而大多数金融推特用户从小就把自己相对于大众的智力优势当作自己的全部身份认同。是的，我也一样有罪……住在玻璃房子里的人不应该扔石头等等……但重点仍然成立，就像我之前说的，表面上最负盛名的基金中 99% 的人，在智力上至少比 Shaun 或 AI 实验室的核心研究人员低一个标准差。只是你的社会环境让你免受这一现实的影响，它提高了在服用阿得拉时精确建模的感知价值，同时低估了发散性思维对产生阿尔法收益的指数级促进作用。"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": 0, "url": "https://x.com/i/status/2116990944301973933", "en": "Sure and regardless of intellect or process the real world will bitchslap you in the face and humble you.  \n\nBut the original chirp wasn’t questioning degree of certainty it was making the mistake of conflating precision vs ability to analyze, abstract and predict.", "zh": "当然，无论智力或过程如何，现实世界都会扇你耳光并让你谦卑。但最初的批评并不是质疑确定性的程度，而是犯了将精确性与分析、抽象和预测能力混为一谈的错误。"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": 0, "url": "https://x.com/i/status/2117039690649911522", "en": "Well within the realm of possibility and only socially tenable if the U.S. goes to war with the rest of the world by hoarding access to the frontier", "zh": "嗯，这完全有可能，并且只有在 U.S. 通过垄断前沿技术的获取权而与世界其他地区开战时，才在社会上站得住脚。"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": 0, "url": "https://x.com/i/status/2117038995536281895", "en": "Correct. And the dirty secret is despite the “best” senior PMs at the pods spending half their day constantly talking to new potential candidates that will go often years at a stretch before finding a true outlier given how rare true talent is.  \n\nThe mediocre PMs that bounce around pods are the ones who settle for analysts or sub-PMs who are “good enough” within a narrow strategy and inevitably their PnL either doesn’t scale or they crush for three years and then blow up.   \n\nThat’s why the comp packages citadel occasionally offers are so wide from baseline.  And it’s why shops that standardize comp are relegated to mediocrity or need Izzy to bail them out.", "zh": "正确。而肮脏的秘密是，尽管 pod 中“最好的”高级 PM 每天花一半时间不断与新潜在候选人交谈，但鉴于真正的人才多么稀有，他们往往要连续几年才能找到一个真正的异常值。那些在 pod 之间跳来跳去的平庸 PM 是那些在狭窄策略内满足于“足够好”的分析师或副 PM 的人，他们的 PnL 要么无法扩展，要么他们 crush 三年然后爆仓。这就是为什么 Citadel 偶尔提供的薪酬方案与基线相差如此之大。这也是为什么标准化薪酬的商店沦为平庸或需要 Izzy 来拯救它们的原因。"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": 0, "url": "https://x.com/i/status/2116996161756082628", "en": "Tbf that is not what most of the chirps criticized or even referred to", "zh": "公平地说，这不是大多数批评所批评甚至提到的内容。"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": null, "url": "https://x.com/i/status/2116996889455337971", "en": "Lmao", "zh": "笑死"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": null, "url": "https://x.com/i/status/2116982902449914222", "en": "Correct", "zh": "正确"}, {"u": "TMTLongShort", "t": "11-02", "l": null, "r": null, "url": "https://x.com/i/status/2117022787814756377", "en": "He has a PhD in physics from caltech and I’m basing my assessment of his intellect based on observing how he synthesizes information", "zh": "他拥有加州理工学院的物理学博士学位，而我对他智力的评估是基于观察他如何综合信息。"}]}, {"id": "n37", "themes": ["公司"], "date": "2026-10-28", "time": "10-28", "tickers": [], "accounts": ["TMTLongShort"], "tweets": [{"u": "TMTLongShort", "t": "10-28", "l": null, "r": 2, "url": "https://x.com/i/status/2115186834045297083", "en": "“We've also begun drug discovery efforts of our own.”", "zh": "我们也已经开始了自己的药物发现工作。"}]}, {"id": "n38", "themes": ["宏观"], "date": "2026-10-28", "time": "10-28", "tickers": [], "accounts": ["TMTLongShort"], "tweets": [{"u": "TMTLongShort", "t": "10-28", "l": null, "r": 31, "url": "https://x.com/i/status/2115114421823357068", "en": "When white collar gets gutted people are going to assume they behave the same way their lower IQ unemployed counterparts do and that is far from the case.  \n\nThe modern economy has been built around channeling medium-agency  high-intellect individuals into institutionalized slop factories that tamper their innate instincts and the second that construct crumbles you get the Russian and French Revolutions or the Meiji Restoration. \n\nThe problem with unemployed intelligent people is they can manipulate their less intelligent conspirators and marshal resources in a way that you would never see in the slums of Chicago. \n\nThe only solution is to convince them they are A. Better off than they were before and B. They are better off than the rest of the world.  \n\nAnything less and you are playing with societal fire.", "zh": "当白领阶层被掏空时，人们会假设他们的行为与那些智商较低的无业者相同，但事实远非如此。现代经济一直围绕着将中等能动性、高智力的个体引导到制度化的低效工厂中，这些工厂会篡改他们天生的本能，而一旦这种结构崩溃，你就会看到俄国和法国大革命或明治维新。失业的聪明人的问题在于，他们能够操纵那些不如他们聪明的同谋者，并以你在芝加哥贫民窟永远看不到的方式调动资源。唯一的解决方案是说服他们：A. 他们比以前过得更好；B. 他们比世界其他地方的人过得更好。任何不足都是在玩火自焚。"}, {"u": "TMTLongShort", "t": "10-28", "l": null, "r": 0, "url": "https://x.com/i/status/2115164510369845432", "en": "For higher intellect white collar “landing on their feet” will feel catastrophic if it results in a degradation of income and status", "zh": "对于高智力的白领来说，如果“站稳脚跟”导致收入和地位下降，他们会觉得这是灾难性的。"}, {"u": "TMTLongShort", "t": "10-28", "l": null, "r": 0, "url": "https://x.com/i/status/2115129135408509251", "en": "That’s exactly my point.", "zh": "这正是我的观点。"}, {"u": "TMTLongShort", "t": "10-28", "l": null, "r": 0, "url": "https://x.com/i/status/2115133479662797254", "en": "Most of them don’t have families and some have bought rural real estate", "zh": "他们中的大多数人没有家庭，有些人购买了乡村房产。"}, {"u": "TMTLongShort", "t": "10-28", "l": null, "r": 0, "url": "https://x.com/i/status/2115117508533289132", "en": "No one is starving in Paris tbf", "zh": "说实话，巴黎没有人挨饿。"}]}, {"id": "n35", "themes": ["公司"], "date": "2026-11-21", "time": "11-21", "tickers": [], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-21", "l": 928, "r": 100, "url": "https://x.com/i/status/2123973467724754956", "en": "USA Din Tai Fung is the worst dumpling place ever, especially the Bay Area's Westfield Valley Fair location. Some of the waiters and cooks don't even speak Chinese. There's a higher ratio of Asians at a Philz Coffee than at a Din Tai Fung.\n\nDumplingMAX UnderPerform. Literally would recommend any other dumpling place. That being said, Taiwan's Din Tai Fung is amazing.", "zh": "美国鼎泰丰是最差的饺子馆，尤其是湾区Westfield Valley Fair分店。有些服务员和厨师甚至不会说中文。Philz Coffee里的亚洲人比例都比鼎泰丰高。"}]}, {"id": "n36", "themes": ["产业·半导体"], "date": "2026-11-21", "time": "11-21", "tickers": [], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-21", "l": 128, "r": 24, "url": "https://x.com/i/status/2123823657747087852", "en": "This conference season, Ayar Labs put real manufacturing statistics on its SuperNova ELSFPs. More than 100 laser units were measured at 50 C with -20 dB back reflections to simulate imperfections in fiber connectors and fiber-to-PIC coupling. The notable stats include a mean RIN of -158 dB/Hz and an especially low mean linewidth of 0.16 MHz, comparable to what 400ZR coherent class lasers are specified at; giving a lot of margin for DWDM operation. Importantly, every laser met spec with margin, which matters a lot more in production than one device achieving extraordinary performance.", "zh": "本会议季，Ayar Labs公布了其SuperNova ELSFP的真实制造统计数据。在50°C下测量了100多个激光单元，并施加-20 dB背向反射以模拟光纤连接器和光纤到PIC耦合中的缺陷。值得注意的统计数据包括平均RIN为-158 dB/Hz，以及特别低的平均线宽0.16 MHz，与400ZR相干级激光器的规格相当；为DWDM操作提供了很大余量。重要的是，每个激光器都符合规格并有余量，这在生产中比单个器件实现非凡性能重要得多。"}]}, {"id": "n37", "themes": ["宏观", "产业·AI算力"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-20", "l": 189, "r": 14, "url": "https://x.com/i/status/2123602891713708464", "en": "Before the election, we called a prolonged Texas permit freeze the biggest risk to our US datacenter forecast. Texas then elected the candidate who campaigned on a moratorium: Gina Hinojosa beat Greg Abbott. \n\n{Map shows the 10 states with the largest 2028 net additions that elected a governor on Nov. 3; states without a race are excluded.} (1/5)🧵", "zh": "选举前，我们曾将得克萨斯州长期暂停许可称为美国数据中心预测的最大风险。随后得州选出了以暂停令为竞选纲领的候选人：吉娜·伊诺霍萨击败了格雷格·阿博特。"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 20, "r": 1, "url": "https://x.com/i/status/2123602893789962391", "en": "Georgia and Ohio also elected governors who ran on pausing new datacenter construction. (2/5)", "zh": "佐治亚州和俄亥俄州也选出了主张暂停新建数据中心建设的州长。"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 29, "r": 0, "url": "https://x.com/i/status/2123602894586818740", "en": "What that changes, using the numbers we published before the vote:\n🟠  2027 is largely locked in. Roughly three-quarters of the GW due across our top 20 states is already under construction.\n🟠  2028 is the fight. Texas alone adds close to 30% of US GW in 2028. (3/5)", "zh": "基于我们在投票前发布的数字，这改变了什么：🟠 2027年基本锁定。在我们前20个州中，约四分之三的待建GW已处于建设中。🟠 2028年是争夺焦点。仅得克萨斯州就贡献了2028年美国GW的近30%。"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 34, "r": 3, "url": "https://x.com/i/status/2123602895513755882", "en": "Texas environmental permits have been frozen since Sept. 21. Hinojosa wants a moratorium until the legislature passes new rules, and the regular session runs Jan. 12 to May 31. (4/5)", "zh": "得克萨斯州的环境许可自9月21日起被冻结。伊诺霍萨希望暂停发放许可，直到立法机构通过新规则，而例会期为1月12日至5月31日。"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 22, "r": 1, "url": "https://x.com/i/status/2123602896377753784", "en": "If approvals stay on hold through that session, the freeze lasts about eight months. If reopening waits for new rules to take effect in late summer, it lasts close to a year. (5/5)", "zh": "如果审批在整个会期持续搁置，冻结将持续约八个月。如果重新开放要等到新规则在夏末生效，则冻结将持续近一年。"}]}, {"id": "n39", "themes": ["产业·AI算力", "产业·半导体"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-20", "l": 532, "r": 43, "url": "https://x.com/i/status/2123495013938073687", "en": "MEME ALERT🚨: PS5 Pro consoles have largely sold out across the globe due to the GTA 6 launch. One GB300 NVL72 rack has about 38 TB of memory, and those DRAM production lines could have been producing the GDDR6 memory needed by GTA GAMERS.\n\nEACH GB300 NVL72 RACK HAS THE EQUIVALENT OF OVER 2,000 PS5 PRO CONSOLES' WORTH OF MEMORY.\n\nThis means each GB300 rack has caused over 2,000 gamers to be unable to play GTA 6.", "zh": "梗图预警🚨：由于《GTA 6》发售，PS5 Pro 主机在全球大部分地区已售罄。一个 GB300 NVL72 机架约有 38 TB 内存，而这些 DRAM 生产线本可以生产 GTA 玩家所需的 GDDR6 内存。每个 GB300 NVL72 机架的内存相当于超过 2,000 台 PS5 Pro 主机的内存总和。这意味着每个 GB300 机架导致超过 2,000 名玩家无法玩《GTA 6》。"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 21, "r": 0, "url": "https://x.com/i/status/2123500034956398837", "en": "Gamers must rise up ✊", "zh": "玩家们必须站起来 ✊"}]}, {"id": "n40", "themes": ["产业·AI算力"], "date": "2026-11-20", "time": "11-20", "tickers": ["NVDA"], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-20", "l": 714, "r": 89, "url": "https://x.com/i/status/2123465108193992939", "en": "AI racks are now too heavy for most old datacenters. An Nvidia GB300 NVL72 rack weighs 1,590kg once its liquid cooling loop is filled. A typical server rack in 2011 weighed about 450kg, and Nvidia puts next year’s Vera Rubin rack at roughly 4,000lb. Filled, weight per square foot of floor is up 3.5x since 2011 and heading to 4x. (1/3)🧵", "zh": "AI机架现在对大多数老旧数据中心来说太重了。英伟达GB300 NVL72机架在液冷回路注满后重达1,590公斤。2011年典型服务器机架重约450公斤，而英伟达预计明年的Vera Rubin机架重约4,000磅。注满后，每平方英尺地板的重量自2011年以来增加了3.5倍，并正朝着4倍发展。(1/3)🧵"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 71, "r": 3, "url": "https://x.com/i/status/2123465110232408488", "en": "The coolant alone, a mix of water and propylene glycol, adds roughly 500 to 1,000lb. Most datacenter floors were built for the 2011 rack. The industry standard (TIA-942) asks for 150 to 250lb per square foot, or 7 to 12kPa. A GB300 rack puts about 17kPa on its own footprint dry and 22kPa filled. Multistory sites in Singapore are rated 5 to 15kPa per floor. (2/3)", "zh": "仅冷却液（水和丙二醇的混合物）就增加了约500至1,000磅。大多数数据中心地板是为2011年的机架建造的。行业标准（TIA-942）要求每平方英尺150至250磅，即7至12kPa。一个GB300机架在其自身占地面积上干燥时施加约17kPa，注满后为22kPa。新加坡的多层站点每层额定为5至15kPa。(2/3)"}, {"u": "SemiAnalysis_", "t": "11-20", "l": 62, "r": 1, "url": "https://x.com/i/status/2123465112136663437", "en": "Racks ship dry and are filled in the hall. A dry GB300 fits the standard 1,500kg freight lift and a filled one does not, so the lift sees the dry rack and the floor carries the filled one. Raising an upper floor’s rating means strengthening slabs, beams, columns and foundations, often in post-tensioned concrete that cannot be cut. Coolant pipes and busway hung above the racks add more load. New AI capacity goes into single story halls or buildings designed for the weight from the start. (3/3)", "zh": "机架以干燥状态运输，并在机房内注液。干燥的GB300适合标准的1,500公斤货运电梯，而注满的则不适合，因此电梯看到的是干燥机架，而地板承载的是注满的机架。提高上层楼板的额定值意味着加固楼板、梁、柱和地基，通常采用无法切割的后张混凝土。悬挂在机架上方的冷却液管道和母线槽增加了更多负载。新的AI容量进入单层大厅或从一开始就为重量设计的建筑。(3/3)"}]}, {"id": "n41", "themes": ["产业·AI算力"], "date": "2026-11-23", "time": "11-23", "tickers": [], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-23", "l": 728, "r": 55, "url": "https://x.com/i/status/2124684387761430549", "en": "Cerebras loves to claim that their output interactivity is 2000 tok/s/user on Kimi K3.1 2.8T, but based on their demo (YouTube video “Cerebras Demo: Running Kimi K3.1 at 2,000 Tokens/Sec”), that is only for short contexts with a context prompt less than 100 tokens long.\n\nInteresting that they don’t show their p99 TPOT at medium (100k+) to long contexts (600k+) on agentic multi-turn workloads, which would affect performance as they need to load the KV cache for all of the previous tokens in the context for Kimi K3.1 Pro’s Gated MLA layers (full attention).\n\nAlso somewhat misleading is that whenever they quote a GB300 NVL72, they quote it at the maximum power of 150kW per rack. Based on our GB300 experiments with Kimi K3.1 Pro on GB300 NVL72 low-latency megakernels, the measured all-in rack power is less than 30% of maximum power, as low latency is memory-bound.\n\nWe welcome Cerebras to demonstrate their claims on AgentX Preview if they are actually confident in them, as it tests all of the things that their marketing does not. We wonder what excuse (coping) they will give this time to avoid demonstrating their claims, considering the tests take less than a couple of hours and can be done during off-peak hours.", "zh": "Cerebras 喜欢宣称他们在 Kimi K3.1 2.8T 上实现了每用户 2000 tok/s 的输出交互性，但根据他们的演示（YouTube 视频“Cerebras Demo: Running Kimi K3.1 at 2,000 Tokens/Sec”），这仅适用于上下文提示长度小于 100 个 token 的短上下文。"}, {"u": "SemiAnalysis_", "t": "11-23", "l": 43, "r": 2, "url": "https://x.com/i/status/2124696109667008754", "en": "InferenceX is free. We would love to benchmark Cerebras for free if they actually stop dodging with excuses, any time of the day, including during off-peak hours in the middle of the night. @andrewdfeldman @seanlie\n\nAgentX/InferenceX is the industry-standard platform to demonstrate that and includes perf-per-dollar and perf-per-watt normalization.", "zh": "有趣的是，他们并未展示在中等（100k+）到长上下文（600k+）的智能体多轮工作负载下的 p99 TPOT，而这会影响性能，因为他们需要为 Kimi K3.1 Pro 的门控 MLA 层（全注意力）加载上下文中所有先前 token 的 KV 缓存。"}]}, {"id": "n42", "themes": ["产业·AI算力", "产业·半导体"], "date": "2026-11-23", "time": "11-23", "tickers": [], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-23", "l": 396, "r": 36, "url": "https://x.com/i/status/2124637709176016998", "en": "BREAKING NEWS🚨: New SGLang Rubin NVL72 submission delivers 6.5x better performance per dollar than GB300 NVL72🚨. SGLANG IS NOT A CAR! 🚨 \n\nThis is done on the new OSS Kimi K3.1 Pro model architecture, which is less than 3 weeks old and has over 2.8 trillion parameters (similar in parameter count to Anthropic Fable 5).", "zh": "突发新闻🚨：新的 SGLang Rubin NVL72 提交实现每美元性能比 GB300 NVL72 高出 6.5 倍🚨。SGLANG 不是汽车！🚨"}]}, {"id": "n44", "themes": ["公司"], "date": "2026-11-19", "time": "11-19", "tickers": ["NVDA"], "accounts": ["SemiAnalysis_"], "tweets": [{"u": "SemiAnalysis_", "t": "11-19", "l": 419, "r": 49, "url": "https://x.com/i/status/2123197114435928513", "en": "ALERT🚨: Nvidia held its employee all-hands today, but didn’t take questions from employees.\n\nThe executives on stage were Colette Kress, Chair of the Board Harvey Jones, Ian Buck, Dwight Diercks, Jonah Alben, Kristin Major, Michael Kagan, Deb Shoquist, Allison Wagonfeld, Nick Parker, Andrew Bell, and Jeff Fisher.\n\nNoticeably absent was Tim Teter (Nvidia’s General Counsel), who has agreed to testify to Congress on December 2.", "zh": "警报🚨：英伟达今天举行了员工全员大会，但没有接受员工提问。"}]}, {"id": "n47", "themes": ["产业·半导体", "公司"], "date": "2026-11-04", "time": "11-04", "tickers": ["AMD", "INTC"], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-04", "l": 195, "r": 37, "url": "https://x.com/i/status/2117949868647825649", "en": "Starting next quarter, AMD will surpass Intel in quarterly revenues. First time in history. $AMD $INTC", "zh": "从下个季度开始，AMD的季度营收将超过英特尔。史上首次。$AMD $INTC"}, {"u": "Omercheema", "t": "11-04", "l": 4, "r": 0, "url": "https://x.com/i/status/2117956203179327965", "en": "That's AI.", "zh": "这就是AI。"}]}, {"id": "n48", "themes": ["产业·半导体", "公司"], "date": "2026-11-03", "time": "11-03", "tickers": ["MRVL"], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-03", "l": 43, "r": 3, "url": "https://x.com/i/status/2117533295453802977", "en": "My biggest concern about Marvell's acquisition of Lumentum was valuation. Semi stocks are in a correction, and $115B could look expensive in a couple of years if AI adoption hits a roadblock.\n\nI have changed my mind. Marvell is paying in stock, not cash. If the broader semi market corrects further, the dollar value of the deal falls with it. That is built-in risk mitigation, and Marvell keeps the upside if AI adoption stays on track.", "zh": "我对Marvell收购Lumentum最大的担忧是估值。半导体股票正处于回调中，如果AI采用遇到障碍，1150亿美元在几年后可能显得昂贵。"}]}, {"id": "n51", "themes": ["产业·半导体", "公司"], "date": "2026-10-31", "time": "10-31", "tickers": ["INTC"], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "10-31", "l": 28, "r": 2, "url": "https://x.com/i/status/2116210713924378718", "en": "A dinosaur that refuses to change... A few thoughts on Intel cheemaomer.substack.com/p/intel-a-dino…", "zh": "一只拒绝改变的恐龙……关于英特尔的一些思考 cheemaomer.substack.com/p/intel-a-dino…"}, {"u": "Omercheema", "t": "10-31", "l": 1, "r": 0, "url": "https://x.com/i/status/2116565333809012928", "en": "True. T Glass isnt expensive. Even throwing it away wont cost too much.", "zh": "确实。玻璃基板并不贵。就算直接扔掉也不会花太多钱。"}]}, {"id": "n56", "themes": ["公司"], "date": "2026-10-30", "time": "10-30", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "10-30", "l": 21, "r": 4, "url": "https://x.com/i/status/2115966605364756576", "en": "Only the paranoid survive.", "zh": "只有偏执狂才能生存。"}]}, {"id": "n57", "themes": ["公司"], "date": "2026-10-29", "time": "10-29", "tickers": ["MRVL", "LITE"], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "10-29", "l": 29, "r": 0, "url": "https://x.com/i/status/2115728144942702788", "en": "At current valuation, $MRVL buying $LITE would be a terrible deal.", "zh": "按当前估值，$MRVL 收购 $LITE 将是一笔糟糕的交易。"}]}, {"id": "n59", "themes": ["产业·半导体", "产业·AI算力"], "date": "2026-11-20", "time": "11-20", "tickers": ["SNDK"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 599, "r": 63, "url": "https://x.com/i/status/2123633356969775107", "en": "Markets appear to be wrongly interpreting Chinese eSSD cuts as deteriorating demand and NAND oversupply.\n\nPhison CEO commentary today + more context behind $SNDK / Kioxia selloff regarding Trendforce revisions: \n\n- \"Pua attributed China's recent enterprise SSD demand slowdown to GPU shortages since November 2026\"\n\n- \"Without GPUs, additional purchases offer little value, prompting some companies to sell server components on the spot market to recover cash\" \n\n(for context enterprise SSDs are growth driver for NAND)\n\n- \"Chinese cloud giants nevertheless plan substantial GPU prepayments, temporarily tying up capital and delaying procurement of other components.\"\n\n- \"the principal challenge in 2027 would be insufficient supply rather than weakening demand, with persistent AI shortages potentially prompting further procurement and inventory accumulation.\"\n\nMarkets seemed to have wrongly interpreted this as demand destruction + pricing collapse. \n\nWhen Phison CEO attributed it to \n-> GPU shortages \n-> causing procurement timing mismatch \n-> Chinese CSPs needed capital for GPU prepayments, so liquidation in inventory (causing spot price volatility)\n-> timeline shift in order procurement \n\nTLDR: delayed procurement from GPU shortages. there were actual order cuts, but this is deferred procurement not structural demand weakening. \n\nChinese CSPs needed capital for GPU prepayments so they liquidated other inventories in the meantime. \n\nPhison says its inventories are insufficient for anticipated 2027 demand and it's sees this as an opportunity for NAND accumulation. \n\nIt's interesting the bottleneck in China migrated back to GPUs though.", "zh": "市场似乎错误地将中国eSSD削减解读为需求恶化和NAND供应过剩。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 85, "r": 1, "url": "https://x.com/i/status/2123636594511122533", "en": "I mean, I'd say it's generally a good idea to focus on things over a longer horizon where fundamentals + earnings ultimately outweigh short term sector liquidations. \n\nRetail investors are the biggest victims of buy high, sell low sentiment trading.", "zh": "Phison CEO今日评论，以及关于Trendforce修订背后$SNDK/铠侠抛售的更多背景："}, {"u": "aleabitoreddit", "t": "11-20", "l": 50, "r": 2, "url": "https://x.com/i/status/2123647139385684060", "en": "I don't have active positions in $SNDK or Kioxia, but I did see a lot of people panicking unfortunately. \n\nSo I'm just providing nuances regarding GPU bottlenecks and spot market volatility that markets might have overreacted to regarding pricing/demand collapse fears. \n\nThe pair's contract visibility and likely share buybacks over next year or two look pretty compelling if they hold, but lot of uncertainty in markets right now.", "zh": "- “Pua将中国近期企业级SSD需求放缓归因于自2026年11月以来的GPU短缺”"}, {"u": "aleabitoreddit", "t": "11-20", "l": 67, "r": 3, "url": "https://x.com/i/status/2123658899509375175", "en": "Entire AI trade got sold off. I don't own $SNDK but just as a reminder to what they've projected:\n\n- Sandisk's pipeline \"exceeds our supply through the end of the decade\" from October's investor presentations\n- minimum contracted revenue is $93.9B at contractual floor prices (baseline)\n- Management also targeted ~75% operating margins + ~50% adjusted FCF margins to 2030.\n\nSo it's ultimately up to you to decide whether they meet those projections or not.", "zh": "- “没有GPU，额外采购价值不大，促使一些公司在现货市场出售服务器组件以回收现金”（背景：企业级SSD是NAND的增长驱动力）"}]}, {"id": "n60", "themes": ["产业·半导体", "公司"], "date": "2026-11-20", "time": "11-20", "tickers": [], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 363, "r": 15, "url": "https://x.com/i/status/2123598186065559858", "en": "I'm actually very impressed with market-chan. If we look at ESMT numbers today: \n\n> $1.58B MC\n> $747M net cash, $274.7M net inventory from Q3\n> $349.5M in Q3 free cash flow\nAdjusted EV: $559.3M\n\n> Q3 net income: $327M (1.2x annualized P/E)\n> October net income (likely another +$96M added to balance sheet)\n\n- \"DDR2/DDR3 supply to remain constrained into 2027\" \n- \"ASPs to rise Q4\" (consumer demand weakening)\n- \"2027 dividend payout ratio could be 30–50% of earnings\"\n\nSo you're valuing the adj. operating business at $559M, despite them making ~$300m net income a quarter. \n\nEven the AI models I've double checked it with looked at these numbers with disbelief.", "zh": "我实际上对市场酱（市场先生）非常佩服。如果我们看看ESMT今天的数字：\n> 市值15.8亿美元\n> 净现金7.47亿美元，第三季度净库存2.747亿美元\n> 第三季度自由现金流3.495亿美元\n调整后企业价值：5.593亿美元\n\n> 第三季度净利润：3.27亿美元（年化市盈率1.2倍）\n> 10月净利润（可能再增加9600万美元到资产负债表）\n\n- “DDR2/DDR3供应将持续紧张至2027年”\n- “第四季度平均售价将上涨”（消费需求减弱）\n- “2027年股息支付率可能为盈利的30-50%”\n\n所以你对调整后的运营业务估值为5.59亿美元，尽管他们每季度净利润约3亿美元。\n\n即使是我复核过的AI模型，看到这些数字也感到难以置信。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 42, "r": 0, "url": "https://x.com/i/status/2123607088773628330", "en": "Recent Trendforce pricing revisions downward were for NAND, not DDR2/DDR3.\n\nTrendforce actually still expects upward revision on legacy DRAM in 2027, despite spot prices falling in line or slightly than current prices q4.\n\nLegacy memory is for consumers, not AI DC spend and are a different cycle than aggregate ai capex. But it’s a result of players allocating toward AI capacity reallocation, that’s happening now and continues into 2027", "zh": "最近Trendforce的价格下调是针对NAND，而不是DDR2/DDR3。\n\nTrendforce实际上仍预计2027年传统DRAM价格将上调，尽管第四季度现货价格下跌与当前价格持平或略低。\n\n传统内存面向消费者，而非AI数据中心支出，其周期与总体AI资本支出不同。但这是玩家将产能重新分配到AI的结果，这一趋势正在发生并将持续到2027年。"}]}, {"id": "n63", "themes": ["产业·AI算力", "公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["AAPL", "ANT", "GOOGL"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 602, "r": 41, "url": "https://x.com/i/status/2123543880780132572", "en": "$AAPL is now developing its own AI agent offerings to compete vs. $ANT, Meta Muse, Google Gemini, and OpenAI. \n\nGiven on-device inference isn't quite ready yet for complex workflows...\n\n+ Apple isn't really known for doing much in the AI race\n\nThis is pretty positive for aggregate inference demand + infra capex implications (as seen with Meta Muse supply procurement). \n\nIt also kinda follows rumors they were looking to acquire private accelerator companies for their own inference buildout.", "zh": "$AAPL 现在正在开发自己的 AI 代理产品，以与 $ANT、Meta Muse、Google Gemini 和 OpenAI 竞争。鉴于设备端推理尚未完全准备好应对复杂工作流……+ 苹果在 AI 竞赛中并不以有多大作为而闻名。这对总推理需求和基础设施资本开支的影响相当积极（正如 Meta Muse 的供应采购所示）。这也多少符合有关他们寻求收购私营加速器公司以自建推理能力的传闻。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 79, "r": 3, "url": "https://x.com/i/status/2123547462376022017", "en": "I don't know how markets perform short term. Anyone who claims they can give you a clear answer is BSing. \n\nBut, especially since tech is getting sold off from record develeraging + degrossing... short interest is record highs on many names... and we're now seeing a bubble in staples from AI L/S pods being blown up. \n\nIt can snap back faster than people think from a catalyst. \n\nThat being said out of any investment theme from biotech, space, physical AI, cybersecurity: I still believe photonics is the most compelling opportunity.  \n\n+ that many other names in AI have been sold off way beyond what fundamentals suggest.", "zh": "我不知道市场短期表现如何。任何声称能给你明确答案的人都是在胡扯。但是，尤其是科技股因创纪录的去杠杆和去敞口而遭抛售……许多股票的做空兴趣处于历史高位……我们现在看到 AI 多空 pods 被爆导致必需消费品出现泡沫。在催化剂作用下，反弹可能比人们想象得更快。话虽如此，在生物科技、太空、物理 AI、网络安全等任何投资主题中：我仍然认为光子学是最有吸引力的机会。+ 许多其他 AI 股票被抛售的程度远超基本面所暗示。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 49, "r": 1, "url": "https://x.com/i/status/2123546035217928409", "en": "John Ternus is a lot proactive than Tim Cook, so we'll see how he does. \n\nApparently he's the one that pressured $AAPL software team to accelerate Apple's AI roadmap.\n\nEspecially since Apple is currently using $GOOGL cloud (Nvidia/TPUs) for their own bottlenecks + other LLMs like Gemini for Siri. \n\nI don't think Apple is comfortable being dependent on third parties for something that should be in-house.", "zh": "John Ternus 比 Tim Cook 主动得多，所以我们看看他表现如何。显然，正是他施压 $AAPL 软件团队加速苹果的 AI 路线图。尤其是因为苹果目前使用 $GOOGL 云（Nvidia/TPUs）来解决自身瓶颈，并用 Gemini 等其他 LLM 支持 Siri。我认为苹果不习惯在理应内部完成的事情上依赖第三方。"}]}, {"id": "n64", "themes": ["公司"], "date": "2026-11-20", "time": "11-20", "tickers": ["ANT", "META"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 776, "r": 28, "url": "https://x.com/i/status/2123488317425820130", "en": "Wow $ANT at a $1.74T valuation…\n\nis now worth hundreds of billions more than $META.\n\nDid anyone end up investing?", "zh": "哇，$ANT 估值达到 1.74 万亿美元……"}]}, {"id": "n65", "themes": ["公司", "产业·半导体"], "date": "2026-11-19", "time": "11-19", "tickers": ["COHR"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-19", "l": 1276, "r": 90, "url": "https://x.com/i/status/2123401652782923980", "en": "That’s the signal of confidence I like to see: $COHR issues a new $2B share buyback, through open market purchases.\n\nOptical industry looks very undervalued right now, especially as it reaches the inflection of the next supercycle.\n\nWe’re already seeing photonics-SOI substrate players go from $25M revenue -> $1.2B LTAs signed in a quarter.\n\nOr $100M backlog -> $500M in a quarter with InP substrates.\n\nAnd we’ll see acceleration for lasers, modules, and the optical supply chain next.\n\nI’m sure Coherent finds its own valuation very low now too, especially after signing $20B LTAs recently.", "zh": "这就是我喜欢看到的信心信号：$COHR 通过公开市场购买，发起了一项新的20亿美元股票回购。"}]}, {"id": "n68", "themes": ["产业·AI算力", "公司"], "date": "2026-11-16", "time": "11-16", "tickers": ["CRWV", "IREN", "NBIS"], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-16", "l": 55, "r": 9, "url": "https://x.com/i/status/2122013045396259150", "en": "Here’s your weekly compute debrief, covering market swings, GPU pricing, and infra shifts:\n\n→ $CRWV is reportedly seeking an investment-grade loan of at least $4 billion (backed by chips and a Meta contract) at a 7%–7.5% yield, which is roughly half the cost of its unsecured debt.\n\n→ $IREN delayed its $4 billion annualized-revenue target into early 2027, while its broader buildout still faces a roughly $6 billion funding gap.\n\n→ $NBIS posted 571% YoY revenue growth, though data-center delays and higher capex guidance weighed on shares.\n\nThe takeaway: Stocks sold off after the midterms and Jensen Huang's exit from Nvidia, but GPU rental rates aren't signaling an AI demand slowdown. Older chips are holding steady (and even climbing), with only the newer B300 softening", "zh": "以下是你的每周算力简报，涵盖市场波动、GPU定价和基础设施变化：\n→ 据报道，$CRWV正寻求一笔至少40亿美元的投资级贷款（以芯片和Meta合同为担保），收益率在7%–7.5%之间，大约是其无担保债务成本的一半。\n→ $IREN将其40亿美元年化营收目标推迟至2027年初，而其更广泛的扩建仍面临约60亿美元的资金缺口。\n→ $NBIS公布了571%的同比营收增长，但数据中心延迟和更高的资本支出指引拖累了股价。\n要点：中期选举后以及黄仁勋离开英伟达后，股票遭到抛售，但GPU租赁费率并未显示AI需求放缓。较旧的芯片保持稳定（甚至上涨），只有较新的B300走软。"}, {"u": "OrnnExchange", "t": "11-16", "l": 58, "r": 5, "url": "https://x.com/i/status/2124869327794925947", "en": "Billions are pouring into compute powering the AI boom, but the market still hasn't agreed on what compute is worth.\n\nWithout shared pricing benchmarks and standardized contracts, there's no reliable rate to hedge, lend against, or trade on.\n\nWe partnered with @Sphere_labs and @FourPillarsFP to explore what it takes to build a real commodity market for compute.\n\nRead the report: research.4pillars.io/en/research/th…", "zh": "数十亿美元正涌入为AI热潮提供动力的算力，但市场仍未就算力的价值达成共识。\n由于缺乏共享的定价基准和标准化合同，没有可靠的费率可用于对冲、借贷或交易。\n我们与@Sphere_labs和@FourPillarsFP合作，探讨建立真正的算力大宗商品市场需要什么。\n阅读报告：research.4pillars.io/en/research/th…"}]}, {"id": "n69", "themes": ["产业·AI算力"], "date": "2026-11-15", "time": "11-15", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-15", "l": 96, "r": 4, "url": "https://x.com/i/status/2121709067617894747", "en": "Excited to see the Ornn Compute Price Index on @FoxBusiness today.\n\nOur index tracks market-clearing GPU prices so builders, investors and operators can see what the market actually paid.\n\nExplore our data → data.ornn.com/analytics", "zh": "很高兴看到Ornn算力价格指数今天在@FoxBusiness上亮相。"}]}, {"id": "n70", "themes": ["产业·AI算力", "公司"], "date": "2026-11-14", "time": "11-14", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-14", "l": 30, "r": 5, "url": "https://x.com/i/status/2121276653724664170", "en": "@AnthropicAI’s S-1 discloses $895 billion in compute commitments. How much revenue does Anthropic need to cover them?\n\nCovering its average annual commitments from late 2027 through 2030 would take roughly $200 billion in annual revenue. That’s about 3x its current run rate.\n\nRead the research: substack.com/home/post/p-22…", "zh": "@AnthropicAI的S-1文件披露了8950亿美元的算力承诺。Anthropic需要多少收入才能覆盖这些承诺？"}]}, {"id": "n71", "themes": ["产业·AI算力"], "date": "2026-11-13", "time": "11-13", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-13", "l": 47, "r": 8, "url": "https://x.com/i/status/2120969630294421504", "en": "What if $1 trillion in compute spending still is not enough?\n\nOur Co-founder & CEO @bavaria_kush joined @Blockspacepod to unpack the true scale of compute needs and what forward rates could look like as demand surges.\n\nWatch below ↓", "zh": "如果1万亿美元的算力支出仍然不够呢？我们的联合创始人兼CEO @bavaria_kush 做客 @Blockspacepod，深入解析算力需求的真实规模，以及随着需求激增远期利率可能呈现的走势。观看下方视频 ↓"}, {"u": "OrnnExchange", "t": "11-13", "l": 30, "r": 3, "url": "https://x.com/i/status/2124966209380876655", "en": "What if GPU financing didn't require locking buyers into 5 to 7-year contracts?\n\nOur co-founder & CTO @Wayne_nelmz joined @Konyk001 on @WCMC_Podcast to discuss how compute price indices and futures could help financiers hedge GPU price risk, enable shorter contracts, and get more GPUs deployed.\n\nWatch the full conversation:", "zh": "如果GPU融资不需要将买家锁定在5至7年的合同中呢？我们的联合创始人兼CTO @Wayne_nelmz 与 @Konyk001 在 @WCMC_Podcast 上讨论了算力价格指数和期货如何帮助融资方对冲GPU价格风险、实现更短期的合同，并部署更多GPU。观看完整对话："}]}, {"id": "n72", "themes": ["产业·AI算力"], "date": "2026-11-12", "time": "11-12", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-12", "l": 80, "r": 21, "url": "https://x.com/i/status/2120888848007811332", "en": "Most GPU price indexes track listed rates. We track what buyers paid.\n\nOver the past year, transacted prices went up across every generation, led by B200 and H200. While new chips usually push down prices for the one before them, B200 kept climbing even after B300 arrived in June.\n\nExplore our data → data.ornn.com/analytics", "zh": "大多数GPU价格指数追踪的是挂牌价格。我们追踪的是买家实际支付的价格。"}]}, {"id": "n73", "themes": ["产业·AI算力", "公司"], "date": "2026-11-12", "time": "11-12", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-12", "l": 18, "r": 1, "url": "https://x.com/i/status/2120663294671221037", "en": "@AnthropicAI’s S-1 has been making headlines, specifically its $895 billion committed to compute, roughly half of which is due by the end of 2030.\n\nThose commitments, spread across Google, Amazon, Microsoft, Broadcom, SpaceX, and others, come with some hard questions. How much revenue does Anthropic need to pay the bill? And what happens if demand falls short of the plan, or runs past it?\n\nRead the full breakdown is in our latest research: ornncompute.substack.com/p/will-anthrop…", "zh": "@AnthropicAI 的 S-1 文件登上头条，尤其是其 8950 亿美元的算力承诺，其中约一半需在 2030 年底前支付。"}]}, {"id": "n74", "themes": ["宏观"], "date": "2026-11-11", "time": "11-11", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-11", "l": 27, "r": 1, "url": "https://x.com/i/status/2120533738211979648", "en": "Tokenization makes private assets easier to trade. It doesn't make them easier to price.\n\nOur co-founder and CTO @wayne_nelmz spoke with Bloomberg on why price transparency means indexing true market-clearing prices. \n\nMore on @business: bloomberg.com/news/newslette…", "zh": "代币化让私募资产更容易交易，但并没有让它们更容易定价。"}]}, {"id": "n75", "themes": ["产业·AI算力"], "date": "2026-11-11", "time": "11-11", "tickers": [], "accounts": ["OrnnExchange"], "tweets": [{"u": "OrnnExchange", "t": "11-11", "l": 63, "r": 6, "url": "https://x.com/i/status/2120258550488338902", "en": "Today we’re launching Ornn Depreciation Curves, modeling GPU hardware values from A100 to GB300 using real transaction data.\n\nAs new generations of GPUs enter the market, the future value of existing hardware becomes increasingly uncertain.\n\nDepreciation Curves provides a foundation for estimating GPU residual values, helping lenders and fleet operators better quantify the risks underlying financing and investment decisions.\n\nExplore the curves → data.ornn.com/analytics", "zh": "今天我们推出Ornn折旧曲线，利用真实交易数据对从A100到GB300的GPU硬件价值进行建模。"}]}, {"id": "n80", "themes": ["公司", "产业·半导体"], "date": "2026-11-12", "time": "11-12", "tickers": ["NVDA", "AMD"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-12", "l": 31, "r": 0, "url": "https://x.com/i/status/2120893778030702638", "en": "I still think Ian Buck is a strong option at NVDA. But here’s a crazy thought: I wonder if Lisa $AMD could be offered the $NVDA job - NVDA acquires AMD. Regulators would probably block it so this is only a dream 💭", "zh": "我仍然认为伊恩·巴克（Ian Buck）是英伟达（NVDA）的有力人选。但这里有个疯狂的想法：我在想，莉莎（苏姿丰）执掌的AMD（$AMD）是否可能被提供英伟达的职位——即英伟达收购AMD。监管机构很可能会阻止这一交易，所以这只是一个梦想💭"}]}, {"id": "n81", "themes": ["产业·半导体", "公司"], "date": "2026-11-12", "time": "11-12", "tickers": ["NVDA"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-12", "l": 58, "r": 1, "url": "https://x.com/i/status/2120689283107520667", "en": "It's almost 1:30am in London - I will be on Bloomberg TV to talk $NVDA and Jensen @BloombergTV . Tune in. I doubt many investors are sleeping much tonight.", "zh": "伦敦现在快凌晨1点半了——我将上彭博电视谈$NVDA和黄仁勋@BloombergTV。敬请收看。我怀疑今晚没多少投资者能睡得着。"}]}, {"id": "n85", "themes": ["公司"], "date": "2026-11-06", "time": "11-06", "tickers": ["AAOI"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-06", "l": 37, "r": 0, "url": "https://x.com/i/status/2118472569346982283", "en": "$AAOI is a land mine in optics - big mistake", "zh": "$AAOI 是光学领域的一颗地雷——重大失误"}]}, {"id": "n86", "themes": ["产业·半导体", "产业·AI算力"], "date": "2026-11-06", "time": "11-06", "tickers": [], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-06", "l": 20, "r": 0, "url": "https://x.com/i/status/2118381633170817225", "en": "Working on new Long ideas - my last 2 Long ideas didn’t work out in this AI/semis massacre 😒", "zh": "正在研究新的做多想法——我最近两个做多想法在AI/半导体股这轮暴跌中都没能成功😒"}]}, {"id": "n87", "themes": ["公司"], "date": "2026-11-05", "time": "11-05", "tickers": ["ANT"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-05", "l": 14, "r": 1, "url": "https://x.com/i/status/2118365501202084335", "en": "Kalshi $ANT IPO still at 77% odds???", "zh": "Kalshi 上 $ANT IPO 的概率仍为 77%？？？"}]}, {"id": "n90", "themes": ["产业·AI算力", "产业·半导体"], "date": "2026-11-04", "time": "11-04", "tickers": [], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-04", "l": 33, "r": 6, "url": "https://x.com/i/status/2118349742426267743", "en": "我昨天指\"Post-training是下一波算力浪潮\"引起了范總和金老師的辯論。我就無意跟任何人辯論了，只是思考了一天，有空就想說下我都想法。\n\n范兄說的話有道理。他指Post-trained開源推理模型小、Token成本小、收集優質data和eval進度慢，所以Post-trained模型帶來的算力和進度也不會很快(應該是和之前AI coding增長相比)。\n\n確實如此，開源推理模型市場本身真的很小，收入只佔總體模型收入的幾%。所以即使開源有明顯增長，可能未來一年都不會為整體算力帶來明顯的增長。而且不能忽視優質data和eval等瓶頸。\n\n我的看法是\n1. 不只開源推理需求在上升，閉源推理需求也上升（增速變慢是確定的）。閉源推理需求很大程度上來自資深工程師、研究員、量化交易員、...等人的需求。對於這部分人來說，支付更多金錢從來不是問題，問題出在模型能力還不夠強，有不低的錯誤率和需要人工 review。模型還在進步當中，所以閉源推理需求上升是確定的。\n\n2. Post-trained開源推理模型增速高於閉源推理增速，這是企業應用AI在workflow的關鍵。當workflow產生又同時帶動非傳統coding更複雜的AI需求(例如code review、security、testing、product design、 ...)\n\n3. 很多人非常看重ROI，但很多公司都不是看ROI，而是看有沒有被新玩家顛覆的風險， token spending作用風險管理策略。\n\n所以未來需求還是會大幅增長，問題從來是需求增速下降會不會導致供大於需。以我找到CSP的渠道，他們有信心2-3年算力繼續供不應求。即使需求增速變慢，供應依然是瓶頸。\n\n對我來說唯一問題是雲能不能維持 >$ 50B/GW以上的暴利收入。我看法是GW收入不一定維持，但是整體半導體和算力依然供不應求。\n\n范兄認為算力和半導體是週期性(下跌)的，長期看好AI，我表示尊重。我認為或許只有部分半導體公司的需求會面臨週期性下跌，會繼續缺貨的還是會繼續缺貨。", "zh": "我昨天指“后训练是下一波算力浪潮”引起了范总和金老师的辩论。我就无意跟任何人辩论了，只是思考了一天，有空就想说下我的想法。"}, {"u": "RYANHINGSHING", "t": "11-04", "l": 4, "r": null, "url": "https://x.com/i/status/2118355323547496489", "en": "補充：供需沒預期中緊張也是一種利潤不及預期的風險，不一定是需求下跌帶來的利潤風險", "zh": "范兄说的话有道理。他指后训练的开源推理模型小、Token成本小、收集优质data和eval进度慢，所以后训练模型带来的算力和进度也不会很快（应该是和之前AI coding增长相比）。"}]}, {"id": "n101", "themes": ["宏观", "产业·半导体"], "date": "2026-11-14", "time": "11-14", "tickers": ["NVDA"], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-14", "l": 217, "r": 38, "url": "https://x.com/i/status/2121632138659520706", "en": "最近看到部分美國媒體和對華鷹派聯手詆毁黃仁勳，並大力推動對中國使用海外算力（包括海外數據中心）採取一刀切限制，我感到非常憤怒。\n\n一方面，我認為某些對華鷹派智庫對AI和半導體理解不足，仔細看他們的報告，會發現大量基礎事實錯誤與邏輯跳躍相當常見。另一方面，他們極力推動的AI芯片全面斷供，他們有沒有收受利益(特別是來自某家美國AI lab)，當時人自己心裏十分清楚。\n\n這些人近期主張的核心是徹底切斷中國獲取海外算力的管道。但從美國自身利益來看，這個主張其實相當短視。\n\n中國企業在海外租用算力，本質上是在向美國的 AI 與半導體生態支付高額費用。這些錢會流進 Nvidia、CSP、以及其他供應鏈，再被重新投入下一輪研發與擴產。換句話說，中國使用海外算力也在為美國生態輸血。\n\n同時，美國其實是中國開源模型的最大受益者。一方面，美國的雲廠商與 inference providers 靠這些開源模型已經累積了可觀的推理 ARR(達10億美元)。另一方面，美國企業在大量非最前沿任務上使用這些模型也是目前性價比最高的選擇。算力層賺走了絕大部分利潤，模型層的中國 lab 實際收到的 licensing fee 卻非常有限，所以美國幾乎一直白嫖中國開源模型\n\n再看 Nvidia 與中國工程師的合作。這些合作並非單方面讓利，而是在持續鞏固 Nvidia AI stack 的生態主導地位。工程師的共同開發、問題回饋與早期適配，反而讓 CUDA 生態更難被替代。\n\n更重要的是，國產算力並非如鷹派想像的那麼不堪一擊。昇騰在硬體規格上已可與 Hopper 相比，部分中國 AI lab 在昇騰上的軟體棧也已進入可用階段。即使單晶片仍非最前沿，中國可以透過芯模協同（算法為晶片設計、晶片為算法優化）、系統工程（超節點、互聯、調度）與開源帶動生態的方式來縮小差距。而多數鷹派只會簡單比較單晶片規格，完全忽略系統層面的可能性。\n\n因此，徹底禁止中國使用 Nvidia 晶片，結果很可能不是鎖死中國，而是加速倒逼中國全面轉向國產 AI 系統。如果徹底禁止中國使用 Nvidia 晶片，我會預期各家中國AI labs將很快使用國產硬件進行萬億規模模型訓練(包括預訓練)。這對美國長期維持技術與生態優勢反而有害。\n\n在我看來，真正需要被質疑的不一定是黃仁勳，而是那些對產業理解不足、卻又極力推動全面斷供、並可能夾帶利益的對華鷹派。", "zh": "最近看到部分美国媒体和对华鹰派联手诋毁黄仁勋，并大力推动对中国使用海外算力（包括海外数据中心）采取一刀切限制，我感到非常愤怒。一方面，我认为某些对华鹰派智库对AI和半导体理解不足，仔细看他们的报告，会发现大量基础事实错误与逻辑跳跃相当常见。另一方面，他们极力推动的AI芯片全面断供，他们有没有收受利益（特别是来自某家美国AI lab），当事人自己心里十分清楚。这些人近期主张的核心是彻底切断中国获取海外算力的管道。但从美国自身利益来看，这个主张其实相当短视。中国企业在海外租用算力，本质上是在向美国的AI与半导体生态支付高额费用。这些钱会流进Nvidia、CSP、以及其他供应链，再被重新投入下一轮研发与扩产。换句话说，中国使用海外算力也在为美国生态输血。同时，美国其实是中国开源模型的最大受益者。一方面，美国的云厂商与inference providers靠这些开源模型已经累积了可观的推理ARR（达10亿美元）。另一方面，美国企业在大量非最前沿任务上使用这些模型也是目前性价比最高的选择。算力层赚走了绝大部分利润，模型层的中国lab实际收到的licensing fee却非常有限，所以美国几乎一直白嫖中国开源模型。再看Nvidia与中国工程师的合作。这些合作并非单方面让利，而是在持续巩固Nvidia AI stack的生态主导地位。工程师的共同开发、问题反馈与早期适配，反而让CUDA生态更难被替代。更重要的是，国产算力并非如鹰派想象的那么不堪一击。昇腾在硬件规格上已可与Hopper相比，部分中国AI lab在昇腾上的软件栈也已进入可用阶段。即使单芯片仍非最前沿，中国可以通过芯模协同（算法为芯片设计、芯片为算法优化）、系统工程（超节点、互联、调度）与开源带动生态的方式来缩小差距。而多数鹰派只会简单比较单芯片规格，完全忽略系统层面的可能性。因此，彻底禁止中国使用Nvidia芯片，结果很可能不是锁死中国，而是加速倒逼中国全面转向国产AI系统。如果彻底禁止中国使用Nvidia芯片，我会预期各家中国AI labs将很快使用国产硬件进行万亿规模模型训练（包括预训练）。这对美国长期维持技术与生态优势反而有害。在我看来，真正需要被质疑的不一定是黄仁勋，而是那些对产业理解不足、却又极力推动全面断供、并可能夹带利益的对华鹰派。"}, {"u": "RYANHINGSHING", "t": "11-14", "l": 5, "r": 0, "url": "https://x.com/i/status/2121655261131915294", "en": "Yes, you’re right. My typo🫡", "zh": "是的，你说得对。我的笔误🫡"}, {"u": "RYANHINGSHING", "t": "11-14", "l": 17, "r": 0, "url": "https://x.com/i/status/2121640354374148389", "en": "只能說CUDA護城河弱化\n產業鏈的關係和系統設計是另一條護城河", "zh": "只能说CUDA护城河弱化，产业链的关系和系统设计是另一条护城河"}, {"u": "RYANHINGSHING", "t": "11-14", "l": 8, "r": 0, "url": "https://x.com/i/status/2121638036081680727", "en": "除了出軌偷食這個行為外😂", "zh": "除了出轨偷食这个行为外😂"}, {"u": "RYANHINGSHING", "t": "11-14", "l": 19, "r": 0, "url": "https://x.com/i/status/2121651038625444254", "en": "你錯判形勢。中國至今仍大量走私Nvidia芯片，中國政府默許走私", "zh": "你错判形势。中国至今仍大量走私Nvidia芯片，中国政府默许走私"}]}, {"id": "n102", "themes": ["产业·AI算力", "公司"], "date": "2026-11-10", "time": "11-10", "tickers": [], "accounts": ["FredaDuan"], "tweets": [{"u": "FredaDuan", "t": "11-10", "l": 25, "r": 3, "url": "https://x.com/i/status/2120214931731775587", "en": "Congrats to \n@QuanquanGu\n and the Geodesic Intelligence team on the launch of NovaAtom-Lite!\n\nParticularly impressive to see what a small team has been able to accomplish in just a few months. Based on the reported results, NovaAtom-Lite appears to outperform Isomorphic Labs’ IsoDDE and Google DeepMind’s AlphaFold 3 on this specific antibody-antigen structure prediction benchmark.\n\nA great example of how a focused team with strong technical talent can move quickly and push the boundaries. \n\nExcited to see progress on AI drug discovery!", "zh": "恭喜 @QuanquanGu 和 Geodesic Intelligence 团队推出 NovaAtom-Lite！"}]}, {"id": "n103", "themes": ["产业·AI算力", "产业·半导体"], "date": "2026-10-26", "time": "10-26", "tickers": ["TSLA"], "accounts": ["FredaDuan"], "tweets": [{"u": "FredaDuan", "t": "10-26", "l": 1100, "r": 237, "url": "https://x.com/i/status/2114772074438988256", "en": "10 Spicy Takes After Talking to 50 Friends at the Frontier of Robotics \n\n1/ Astra IS robotics' GPT-3 moment. Ironically, now that it's finally here, some in robotics seem reluctant to acknowledge it. Perhaps because it (sadly) didn't come from a robotics company?\n\n2/ Robotics is becoming just another vertical for frontier labs. Not so different from coding in some respects. Why reinvent general intelligence for every industry?\n\n3/ Robotics was too hard to underwrite until now. No convincing pretraining scaling law, no convergence on models, data, or hardware. No wonder some critics dismissed it as a fragmented industry playing an expensive \"demo game\". Astra may finally offer a credible path to scale.\n\n4/ Robotics foundation-model startups have a case. But how strong is it? The argument: Astra handles System 2 (reasoning), while specialized models retain System 1 (skills) and System 0 (motor control). Fair. But isn't that already a narrower value proposition? And who says the boundary stops there?\n\n5/ Follow the talent. Word is OpenAI reorganized its 30–40-person robotics team around the core Astra model. Hearing similar moves toward general models at \n@Tesla_Optimus\n. Org charts may tell us more than any demo.\n\n6/ The robotics data gold rush is real. Million-hour procurement programs, some potentially reaching tens of millions of hours. Talk of budgets approaching $1B per frontier lab.\n\n7/ Bullish on robotics hardware volumes. As intelligence becomes more accessible, the barriers to building useful robots could fall dramatically. The moat shifts toward reliability, dexterity, integration, and deployment.\n\n8/ Robotics could fuel the next semiconductor and memory supercycle. A 100B-parameter model running on the edge requires ~50GB just for 4-bit weights. Now multiply that by millions of robots. Why do you think \n@JensenHuang\n is so obsessed with robotics? \n@elonmusk\n saw it coming: \nhttps://\nx.com/elonmusk/statu\ns/2114772074438988256?a=ZJpCuCM8Iv8RkRR_g_A&s=20\n…\n\n9/ Is self-driving immune to the general-model threat? After coding and robotics, why assume self-driving remains the exclusive domain of proprietary, vertical models? Robotaxi increasingly feels like a solved problem to me. But if and when frontier labs move into self-driving, we could see an Apple vs. Android dynamic. Think about the implications for \n$TSLA\n, Waymo, and other OEMs.\n\n10/ The next bottleneck may not be intelligence. It's deployment. Models are improving faster than our ability to deploy robots in the messy real world. Integration, hardware variance, failure recovery, and economics remain brutally hard. The real moat may be turning intelligence into reliable, profitable physical work.\n\n--\nI realize some of these takes may rub people the wrong way, especially those who have spent years doing the hard work of advancing robotics. That's not my intention. \n\nI'm sharing them to spark debate, not to declare winners and losers. Astra has only been out for a month or so, and it's far too early to draw definitive conclusions. More importantly, when the TAM is this enormous - potentially the largest in tech - there should be plenty of room for different approaches and many winners.\n\n++\nFull diligence report: \nhttps://\nrobonomics.substack.com/p/robotics-new\n-era-after-astra?r=3hcp4&utm_campaign=post&utm_medium=web\n…", "zh": "1/ Astra 是机器人领域的 GPT-3 时刻。讽刺的是，当它终于到来时，机器人领域的一些人似乎不愿承认它。也许是因为它（遗憾地）并非来自一家机器人公司？"}, {"u": "FredaDuan", "t": "10-26", "l": 8, "r": null, "url": "https://x.com/i/status/2116955475652804660", "en": "Thanks \n@Yi__Li\n for the comment! Always appreciate thoughtful pushback, especially from people close to the ground. Would genuinely love to hear your perspective on why you disagree and what you’re seeing that I might be missing. Always eager to learn!", "zh": "2/ 机器人技术正在成为前沿实验室的又一个垂直领域。在某些方面与编程并无不同。为什么要为每个行业重新发明通用智能？"}]}, {"id": "n104", "themes": ["公司", "产业·AI算力"], "date": "2026-10-30", "time": "10-30", "tickers": ["TSLA"], "accounts": ["FredaDuan"], "tweets": [{"u": "FredaDuan", "t": "10-30", "l": 95, "r": 18, "url": "https://x.com/i/status/2116310665459909033", "en": "If \n$TSLA\n robotaxi is at $50m (weekly) runrate ARR (which I think is very possible - math below), then that's probably already at 1/10th \n@Waymo\n 's total gross booking?\n\n> TSLA ARR math (all based on public info):\n\n$TSLA\n disclosed 437k miles/week in Austin. Assuming ~3.5 paid trip miles, at $10-15 per trip. That puts it at over $50M ARR. \nObviously this is a weekly runrate, because TSLA has been scaling v quickly, 10x+ in 3 months. \n\n> Waymo math (all based on public info):\nAssuming 500-600k trips per week or ~4,000 cars on the road (Waymo official commentary), and ~$16 per trip (shorter than Uber trips, but comparable on a per-mile basis), Waymo’s current GMV run-rate is ~$500–600m.\n\nhttps://\nrobonomics.substack.com/p/fact-check-o\nn-self-driving-3q26?r=3hcp4&utm_campaign=post-expanded-share&utm_medium=web\n…", "zh": "如果$TSLA的Robotaxi每周运行收入达到5000万美元年化（我认为非常可能——计算如下），那可能已经达到@Waymo总预订量的十分之一？"}]}, {"id": "n74", "themes": ["产业·AI算力"], "date": "2026-11-23", "time": "11-23", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-23", "l": 21, "r": 1, "url": "https://x.com/i/status/2118389341705977961", "en": "THE BEAR THESIS.", "zh": "空头论点。"}, {"u": "Omercheema", "t": "11-23", "l": 20, "r": 0, "url": "https://x.com/i/status/2124864761875615954", "en": "Jensen is back...", "zh": "黄仁勋回来了……"}]}, {"id": "n75", "themes": ["产业·半导体"], "date": "2026-11-06", "time": "11-06", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-06", "l": 71, "r": 5, "url": "https://x.com/i/status/2118367141262999873", "en": "Rule of thumb. Check a semiconductor stock price on April 1st this year. If it is below that price now, it might be a buy. \n\nIf we have three more days like today,  we will be in solid buy territory.", "zh": "经验法则。查看今年4月1日的半导体股票价格。如果现在低于那个价格，可能值得买入。"}, {"u": "Omercheema", "t": "11-06", "l": 0, "r": 0, "url": "https://x.com/i/status/2118407018126201021", "en": "Depends what you are holding", "zh": "如果再有三天像今天这样的行情，我们就会进入坚实的买入区间。"}]}, {"id": "n76", "themes": ["产业·半导体"], "date": "2026-11-02", "time": "11-02", "tickers": [], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "11-02", "l": 36, "r": 2, "url": "https://x.com/i/status/2116940235380600854", "en": "Overall packaging yield can't be higher than the yield of one step in the same process. \n\nThere is something wrong with these numbers.", "zh": "整体封装良率不可能高于同一工艺中某一步骤的良率。这些数字有问题。"}, {"u": "Omercheema", "t": "11-02", "l": 0, "r": 0, "url": "https://x.com/i/status/2117122837538300132", "en": "Possibly.  But substrate manufacturing is done by a partner and it's yield isnt counted as part of the chip maker's yield.", "zh": "有可能。但基板制造由合作伙伴完成，其良率不计入芯片制造商的良率。"}]}, {"id": "n79", "themes": ["产业·半导体", "公司"], "date": "2026-10-30", "time": "10-30", "tickers": ["INTC", "AMD"], "accounts": ["Omercheema"], "tweets": [{"u": "Omercheema", "t": "10-30", "l": 255, "r": 25, "url": "https://x.com/i/status/2116025072486097307", "en": "Israel production issue is not Intel's fault. It's bad luck. \n\nBut, not having enough substrates is absolutely their fault. Head of supply chain deserves getting fired. \n\nAnd messing up PC/Server mix is their fault too. That would require heads of two divisions. \n\nThese people are paid millions to do their job right. They can't just come  in front of investors and make lame excuses.", "zh": "以色列生产问题不是英特尔的错，是运气不好。"}, {"u": "Omercheema", "t": "10-30", "l": 10, "r": 0, "url": "https://x.com/i/status/2116042705214021763", "en": "Correct.  It is mostly an Intel problem.  \n\nSubstrate issue is industry wide and we need to see if AMD has solved it or not.", "zh": "但基板不够绝对是他们的错。供应链负责人应该被解雇。"}]}, {"id": "n84", "themes": ["公司", "产业·半导体"], "date": "2026-11-20", "time": "11-20", "tickers": ["NVDA", "ARM"], "accounts": ["aleabitoreddit"], "tweets": [{"u": "aleabitoreddit", "t": "11-20", "l": 6272, "r": 613, "url": "https://x.com/i/status/2123130933318717529", "en": "I'm hearing multiple things from industry executives:\n\n1. Potential $NVDA employee exodus if Jensen doesn't come back soon.\n\nMany senior management and engineers can easily retire after Nvidia stock appreciation over the years.\n\nThey don't need to continue working sitting on millions in equity. But they continued to work because Jensen was a visionary leader.\n\nUnder new interim CFO (former CFO), it gives an excuse for that lot of people to finally quit soon. A pay bump or hiring $ARM CEO isn't going to change that.\n\nSo you have generational talent leaving.\n\n2. Loss of confidence in $NVDA future growth (Jensen was the moat).\n\nWhat I'm hearing is that Jensen understands heavily top-down architectures, and it's this magical discretionary element that doesn't get covered in media.\n\nWhen cuda, network, and $NVDA internal teams are arguing, Jensen made the final choices around heavily nuanced discretionary decision about where Nvidia + AI ecosystem ends up going:\n\nThen everyone followed. The supply chain, capital, agreements, and faith.\n\nYou also can't suddenly replace the trust that local Taiwanese factories build with Jensen over the years if you bring in external CEOs, or even internal executives.\n\nIt was transformational bet after bet after bet after bet that Jensen made until Nvidia became a former $5T+ company.\n\n3. $NVDA is not that technologically far ahead of others. It's not a 5 year lead, but months ahead to a year in different areas.\n\nJensen was accelerating all of that. Longer Jensen is gone, the longer Nvidia and its competitive ecosystem decays, beyond the current near-term roadmaps.\n\nNvidia's greatest moat was Jensen Huang making high-stake architectural decisions and accelerating capital, suppliers, + the industry to rally around his vision.\n\nThere's a massive loss of confidence in $NVDA with Jensen gone.", "zh": "我从行业高管那里听到多件事：\n1. 如果黄仁勋不尽快回归，$NVDA 可能面临员工离职潮。\n许多高管和工程师在英伟达股票多年上涨后可以轻松退休。\n他们坐拥数百万股权，无需继续工作。但他们继续工作是因为黄仁勋是一位有远见的领导者。\n在新任临时CFO（前CFO）领导下，这给了那批人最终很快辞职的借口。加薪或聘请$ARM CEO不会改变这一点。\n所以你会看到一代人才离开。\n2. 对$NVDA未来增长失去信心（黄仁勋曾是护城河）。\n我听到的是，黄仁勋深刻理解高度自上而下的架构，而这是媒体不会报道的神奇自由裁量元素。\n当cuda、网络和$NVDA内部团队争论时，黄仁勋就英伟达+AI生态系统走向何方做出最终选择，涉及高度微妙的自由裁量决策：\n然后所有人跟随。供应链、资本、协议和信念。\n如果你引入外部CEO，甚至内部高管，你也无法突然取代当地台湾工厂多年来与黄仁勋建立的信任。\n这是黄仁勋一次又一次做出的变革性押注，直到英伟达成为一家曾经市值5万亿美元以上的公司。\n3. $NVDA在技术上并不比其他人领先那么多。这不是5年的领先优势，而是在不同领域领先数月到一年。\n黄仁勋在加速这一切。黄仁勋离开的时间越长，英伟达及其竞争生态系统的衰退就越久，超出当前近期路线图。\n英伟达最大的护城河是黄仁勋做出高风险架构决策并加速资本、供应商+行业围绕他的愿景团结起来。\n黄仁勋离开后，人们对$NVDA的信心大幅丧失。"}, {"u": "aleabitoreddit", "t": "11-20", "l": 117, "r": 1, "url": "https://x.com/i/status/2123571428712931811", "en": "It also doesn’t help Nvidia has credit downgrades because Jensen left… \n\nNot saying it’s all over for $NVDA but there’s extreme uncertainty crowding around the company now", "zh": "这也没有帮助英伟达因黄仁勋离开而遭遇信用评级下调……\n不是说$NVDA一切都结束了，但现在公司周围充斥着极端不确定性"}]}, {"id": "n90", "themes": ["公司"], "date": "2026-11-24", "time": "11-24", "tickers": ["ANT"], "accounts": ["HedgeyeTech"], "tweets": [{"u": "HedgeyeTech", "t": "11-24", "l": 14, "r": 1, "url": "https://x.com/i/status/2120901970227818767", "en": "NOW THAT Nvidia CEO JENSEN HUANG, who has done a fantastic job, has resigned, there is only one man to take his place - TIM COOK of Apple. A Legend replaces a Legend! President DONALD J. TRUMP\n\n( TS: Nov 12 2026, 10:29 AM ET )", "zh": "既然英伟达CEO黄仁勋——他做得非常出色——已经辞职，现在只有一个人能接替他的位置——苹果的蒂姆·库克。一位传奇取代另一位传奇！唐纳德·特朗普总统"}, {"u": "HedgeyeTech", "t": "11-24", "l": 38, "r": 1, "url": "https://x.com/i/status/2124897338489745507", "en": "$ANT - the only stock down in a sea of green", "zh": "$ANT——在一片上涨中唯一一只下跌的股票"}]}, {"id": "n98", "themes": ["宏观", "产业·AI算力"], "date": "2026-11-17", "time": "11-17", "tickers": ["ANT"], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-17", "l": 22, "r": 1, "url": "https://x.com/i/status/2122698386596098424", "en": "還有BIS封堵遠端算力目的是主要限制中國AI公司訓練frontier models(中國AI公司在海外訓練模型)\n\n$ANT 的競爭壓力因此會在短期內會減低，值得更高估值", "zh": "还有BIS封堵远程算力，目的是主要限制中国AI公司训练前沿模型（中国AI公司在海外训练模型）"}, {"u": "RYANHINGSHING", "t": "11-17", "l": 3, "r": 0, "url": "https://x.com/i/status/2122708740243877928", "en": "中國半導體😂\n我等IPO後才買美股半導體", "zh": "$ANT的竞争压力因此短期内会减低，值得更高估值"}]}, {"id": "n99", "themes": ["产业·AI算力"], "date": "2026-11-17", "time": "11-17", "tickers": [], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-17", "l": 28, "r": 3, "url": "https://x.com/i/status/2122697107912249372", "en": "能鎖定算力和domestic-stack integration的獨立模型公司有明顯優勢\nMinimax的infra太差，不太看好...\n目前看來只有deepseek和智譜...", "zh": "能锁定算力和国产技术栈整合的独立模型公司有明显优势"}, {"u": "RYANHINGSHING", "t": "11-17", "l": 0, "r": 0, "url": "https://x.com/i/status/2122705041383637306", "en": "不知道能不能救到他們…", "zh": "Minimax的基础设施太差，不太看好……"}]}, {"id": "n101", "themes": ["产业·AI算力", "宏观"], "date": "2026-11-17", "time": "11-17", "tickers": [], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-17", "l": 86, "r": 5, "url": "https://x.com/i/status/2112466724901810207", "en": "已多次解釋過為什麼大部分中國開源模型公司會卷以及被美系閉源公司斬殺，不再解釋。智譜在期間已下跌70%, 離高點已下跌超85%。 \n\n這次下跌是因為美國對華鷹派打算全面封殺中國獲得美國AI芯片算力，按道理說美國模型會再大幅拉開跟中國開源模型的能力差距。中國推理算力也更少了。\n\n不過中長期看，我不對智譜和deepseek這兩間AI公司悲觀。因為1. 走私算力這些行為很難打擊，能打擊一半走私量已經是超級樂觀了。智譜和deepseek應能較優先取得算力。 2. 智譜和deepseek的infra能力真的很強，對華鷹派這種行為會加速智譜和deepseek使用昇騰訓練萬億規模模型(我說的是做到預訓練)和推理。  昇騰經濟性較差，但畢竟獨立的AI生態圈將會形成。\n\n說起來市場很搞笑，半年前應該悲觀時不悲觀，現在跌了那麼多時又突然極度悲觀了。forward EV/ARR 5x，是不是要悲觀就是見仁見智了😉", "zh": "已经多次解释过为什么大部分中国开源模型公司会内卷以及被美系闭源公司碾压，不再解释。智谱在此期间已下跌70%，离高点已下跌超85%。这次下跌是因为美国对华鹰派打算全面封杀中国获得美国AI芯片算力，按理说美国模型会进一步大幅拉开与中国开源模型的能力差距。中国的推理算力也更少了。不过中长期看，我不对智谱和deepseek这两家AI公司悲观。因为1. 走私算力这些行为很难打击，能打击一半走私量已经是超级乐观了。智谱和deepseek应能较优先取得算力。2. 智谱和deepseek的infra能力真的很强，对华鹰派这种行为会加速智谱和deepseek使用昇腾训练万亿规模模型（我说的是做到预训练）和推理。昇腾经济性较差，但毕竟独立的AI生态圈将会形成。说起来市场很搞笑，半年前应该悲观时不悲观，现在跌了那么多时又突然极度悲观了。forward EV/ARR 5x，是不是要悲观就是见仁见智了😉"}, {"u": "RYANHINGSHING", "t": "11-17", "l": 55, "r": 7, "url": "https://x.com/i/status/2108127671326847464", "en": "Ryan已經多次解釋過為什麼大部分中國開源模型公司會卷, 以及被美系閉源公司斬殺。智譜在期間已下跌56%, 離高點已下跌80%。\n\nOpenAI、Ant、XAI等等公司已經有算力規模優勢，加上新架構滲透率上升、算法優化、人才優勢可以壓低成本。相反，開源模型沒辦法保障海外算力來源，同質化嚴重，議價能力很低。Epoch AI的一篇文章清楚解釋了公開模型權重如何削弱開源模型公司定價能力, 開源模型市佔率越來越分散的現象(H/T @cherylwoooo )\n\n現在美國閉源模型已有成本優勢, 不斷針對老中模型定價來壓制中國開源模型公司的空間", "zh": "Ryan已经多次解释过为什么大部分中国开源模型公司会内卷，以及被美系闭源公司碾压。智谱在此期间已下跌56%，离高点已下跌80%。OpenAI、Ant、XAI等等公司已经有算力规模优势，加上新架构渗透率上升、算法优化、人才优势可以压低成本。相反，开源模型没办法保障海外算力来源，同质化严重，议价能力很低。Epoch AI的一篇文章清楚解释了公开模型权重如何削弱开源模型公司定价能力，开源模型市占率越来越分散的现象（H/T @cherylwoooo）现在美国闭源模型已有成本优势，不断针对老中模型定价来压制中国开源模型公司的空间"}, {"u": "RYANHINGSHING", "t": "11-17", "l": 1, "r": 0, "url": "https://x.com/i/status/2122321114093470184", "en": "這一點有道理🤔", "zh": "这一点有道理🤔"}, {"u": "RYANHINGSHING", "t": "11-17", "l": 3, "r": 0, "url": "https://x.com/i/status/2122474340348567775", "en": "No，中國一樣進入RSI成長區間\n\n唯一分別是Ant有給METR數據測量RSI速度，中國AI labs肯定不願意公布數據", "zh": "不，中国一样进入RSI成长区间。唯一分别是Ant有给METR数据测量RSI速度，中国AI labs肯定不愿意公布数据"}]}, {"id": "n102", "themes": ["宏观"], "date": "2026-11-16", "time": "11-16", "tickers": [], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-16", "l": 224, "r": 3, "url": "https://x.com/i/status/2122216166584435079", "en": "放心，香港不會消失🤔\n\n真香港人會消失，但會多了一群不懂廣東話的「来了就是香港人」🤔", "zh": "放心，香港不会消失🤔"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 24, "r": 0, "url": "https://x.com/i/status/2122254411561066634", "en": "不是，香港以前講的圍頭話也是廣東話，也能跟講廣州話的人溝通。", "zh": "真正的香港人会消失，但会多出一群不懂广东话的“来了就是香港人”🤔"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 9, "r": 0, "url": "https://x.com/i/status/2122257961104101623", "en": "沒錯，同情真上海人😪", "zh": "不是，香港以前讲的围头话也是广东话，也能跟讲广州话的人沟通。"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 3, "r": 0, "url": "https://x.com/i/status/2122253871468954044", "en": "I agree with this historical parallel...", "zh": "没错，同情真上海人😪"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 15, "r": 0, "url": "https://x.com/i/status/2122267908432863698", "en": "因為原po講香港bankers高學歷、聰明、有野心，Elon才回應香港人生育低，所以香港會「消失」", "zh": "我同意这个历史类比……"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 0, "r": 0, "url": "https://x.com/i/status/2122252580361490538", "en": "Hmm, not sure…", "zh": "因为原帖说香港bankers高学历、聪明、有野心，Elon才回应香港人生育低，所以香港会“消失”"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 1, "r": 0, "url": "https://x.com/i/status/2122256194979193142", "en": "閩南語嗎？😂", "zh": "嗯，不确定……"}]}, {"id": "n103", "themes": ["公司"], "date": "2026-11-16", "time": "11-16", "tickers": [], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-16", "l": 39, "r": 1, "url": "https://x.com/i/status/2063132328424316971", "en": "我之前已解讀過康方生物依沃西HARMONi-6在ASCO中臨床數據問題，已提及了依沃西在國際市場受阻的問題。今天FDA向Summit發出CRL，表示依沃西單抗美國首個適應證上市申請暫未獲批，原因就是5個月前ASCO的解讀。\n\n當嘴資、國內媒體、X某些用戶聯合吹高國產藥收割散戶時，散戶就會成韭菜😓\n\n希望以後還有機會說說這些機構賤種行為", "zh": "我之前已解读过康方生物依沃西HARMONi-6在ASCO中的临床数据问题，已提及了依沃西在国际市场受阻的问题。今天FDA向Summit发出CRL，表示依沃西单抗美国首个适应症上市申请暂未获批，原因就是5个月前ASCO的解读。"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 16, "r": 2, "url": "https://x.com/i/status/2061430899682554074", "en": "康方依沃西HARMONi-6數據問題\n\n1. 實驗人群是中國人(想進入外國市場必須有外國人群）\n2. 剔除75歲以上病人(高年齡人士PD-L1有效性下跌, 更高毒性. 全球75歲以上病人佔比高)\n3. OS出現斷崖式下跌(隨訪時間不足導致後期風險人口不足)\n4. 看來對65歲以上人群的沒有幫助(PFS)\n\n媒體吹太大\n\n謝謝大家😅", "zh": "当嘴资、国内媒体、X某些用户联合吹高国产药收割散户时，散户就会成韭菜😓"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 1, "r": 0, "url": "https://x.com/i/status/2122152682211397808", "en": "專業人士炒也難😂", "zh": "希望以后还有机会说说这些机构贱种行为"}, {"u": "RYANHINGSHING", "t": "11-16", "l": 1, "r": 0, "url": "https://x.com/i/status/2122153922462933357", "en": "你是專業🫡", "zh": "康方依沃西HARMONi-6数据问题"}]}, {"id": "n104", "themes": ["产业·半导体", "公司"], "date": "2026-11-15", "time": "11-15", "tickers": ["NVDA"], "accounts": ["RYANHINGSHING"], "tweets": [{"u": "RYANHINGSHING", "t": "11-15", "l": 120, "r": 9, "url": "https://x.com/i/status/2121769493215269146", "en": "Sirin說得真好\n\nNvidia的供應商願意為Nvidia承擔風險是、提前備料和鎖定產能，是因為Jensen累積了長期信譽，願意為失敗承擔失敗的責任，而不是把風險和責任推卸給合作夥伴。而且Jensen有長期敢於提前佈局技術和產業鏈、無視短視的反對聲音的歷史(例如CUDA、CPU)，別人相信他更重視長期技術路線和長期夥伴關係。我不相信美國能找到職業經理人替代Jensen的位置。\n\n會認為Jensen離開Nvidia對Nvidia沒有影響或不會削減美國國力的人，大概是沒有跟供應鏈有任何關係的人。有聊過的人，大概都會跟我一樣這樣說。", "zh": "Sirin说得真好"}, {"u": "RYANHINGSHING", "t": "11-15", "l": 3, "r": 0, "url": "https://x.com/i/status/2121903945144795168", "en": "不敢想像Kress坐在中間😂", "zh": "Nvidia的供应商愿意为Nvidia承担风险、提前备料和锁定产能，是因为Jensen累积了长期信誉，愿意为失败承担失败的责任，而不是把风险和責任推卸给合作伙伴。而且Jensen有长期敢于提前布局技术和产业链、无视短视的反对声音的历史（例如CUDA、CPU），别人相信他更重视长期技术路线和长期伙伴关系。我不相信美国能找到职业经理人替代Jensen的位置。"}]}];
